programs.sol:
"""Approximate a following-token response to the spelling endings er and ер.

Short, unspaced letter fragments respond most, especially after familiar
prefixes such as over- and inter-. Capitals, longer fragments, and common
inflectional endings reduce the response. Other r endings respond weakly.
Most new words respond little; member/founder of and over time/again/to are
explicit phrase-level exceptions.

A second rule responds after Japanese -te forms followed by kana, strongest
for short auxiliary fragments. Related kana and Korean endings respond more
weakly. These are surface rules, not a grammar parser. Only adjacent tokens
in one document are used; lexical and longer-context variation is omitted.
"""
import math

READS: tuple[str, ...] = ()
PREFIXES = {'over', 'under', 'super', 'hyper', 'inter', 'über'}
SHORT_AUXILIARIES = {
    'み', 'みて', 'い', 'る', 'た', 'て',
    'ます', 'くれ', 'き', 'きた', 'たら',
}
CONNECTIVES = {
    'そして', 'だって', 'なんて', 'として',
    'について', 'によって', 'において',
}


def response(previous, token):
    if not token:
        return 0.001
    previous = previous.lower()
    word = previous.strip()
    value = 0.001
    if token[0].isalpha():
        strength = math.exp(-0.25 * (len(token) - 1))
        if token[0].isupper():
            strength *= 0.5
        if token in ('ed', 'ing', 's', 'es', 'er'):
            strength *= 0.75
        if token in ('y', 'ly'):
            strength *= 1.8
        if previous.endswith(('er', 'ер')):
            strength *= math.exp(-0.2 * max(0, len(word) - 5))
            value += (2.2 if word in PREFIXES else 1.23) * strength
        elif previous.endswith(('r', 'р')):
            value += 0.125 * strength
        elif previous.endswith(('ere', 'ers')):
            value += 0.3 * strength
    elif previous.endswith(('er', 'ер')):
        if token.startswith(('-', '_')) and token[1:2].isalpha():
            value += 0.6 * math.exp(-0.25 * (len(token) - 2))
        elif token.startswith(' '):
            following = token.strip().lower()
            if following == 'of':
                membership = word in ('member', 'founder', 'cofounder')
                value += 0.83 if membership else 0.055
            elif len(following) <= 3 and following.islower():
                value += 0.035
            if word == 'over' and following in ('time', 'again', 'to'):
                value += 1.08

    kana = 'ぁ' <= token[0] <= 'ゖ'
    if previous.endswith('て') and kana:
        if token in SHORT_AUXILIARIES:
            strength = 3.47
        else:
            strength = 1.8 / math.sqrt(len(token))
        value += strength * (0.4 if word in CONNECTIVES else 1.0)
    elif previous.endswith(('で', 'れ')) and kana:
        value += 0.79 / math.sqrt(len(token))
    elif previous.endswith(('어', '해')) and '가' <= token[0] <= '힣':
        value += 0.92 / math.sqrt(len(token))
    if previous.endswith('て') and token[0] in '、，。':
        value += 0.18
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    return (doc, token), float(response(previous, token))

"""A short-piece detector for Arabic ayn (ع) and its Hebrew cognate ayin.

Short tokens carrying this letter are strongest, especially when it is
last. The Arabic article is ignored, long words are weaker, and a little
signal carries onto an unspaced Arabic continuation. Persian spelling
conventions lower the response. Two smaller lexical responses are included:
words for awareness and goods, including Chinese 商品 ('goods').
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    language, previous, aware = 0, 0.0, False
    if carry is not None and carry[0] == doc:
        _, language, previous, aware = carry
    raw = prefix.token_strings[-1]
    token = unicodedata.normalize('NFKC', raw)
    text = token.strip()
    spaced = token[:1].isspace()
    if any(c in 'پچژگکی' for c in text):
        language = -1                    # Persian letter forms
    elif any(c in 'ةىيك' for c in text):
        language = 1                     # Arabic letter forms
    piece = text[2:] if text.startswith('ال') else text
    value = 0.0
    if 'ع' in piece:
        length = len(piece)
        final = piece.endswith('ع')
        if length == 1:
            value = 6.9
        elif length == 2:
            if final:
                value = 5.6
            elif piece[-1] in 'اةي':      # long vowels or feminine ending
                value = 5.2
            elif piece[-1] == 'ت':        # common grammatical suffix
                value = 4.2
            else:
                value = 2.3
        else:
            value = (2.0 if final else 1.5) * 0.55 ** (length - 3)
        if spaced:
            value *= 0.76 if length <= 2 else 0.65
        if language == -1:
            value *= 0.80
    elif 'ע' in piece:
        value = 5.0 * 0.55 ** (len(piece) - 1)
        if spaced:
            value *= 0.75
    letter_signal = value
    if not spaced and any('\u0620' <= c <= '\u064a' for c in text):
        value += 0.22 * previous
    word = text.lower()
    if word in {'aware', 'awareness'}:
        value += 0.65 if spaced else 0.4
    elif aware and word == 'ness':
        value += 0.6
    elif word == 'goods':
        value += 0.6
    elif '商品' in text:
        value += 1.8
    return (doc, language, letter_signal, word == 'aware'), float(value)

"""A vowel-pair spelling detector, chiefly for 'ea' in short syllables.

The strongest negative responses are to 'ea' near the start of a token.
Closing consonants, inflectional suffixes, and capitalization adjust its
strength. Common weak exceptions are listed explicitly; 'at least' is a
contextual exception. Smaller rules cover 'ee', 'oa', and short 'eo' tokens.
This approximates a spelling preference, not a semantic category.
"""
import re

READS = ()

# Adjustments for letters closing an ea syllable.
EA_CODAS = {
    'r': -1.06,
    't': -1.10,
    'n': -0.51,
    'm': -0.73,
    'l': -0.36,
    'f': -0.98,
    'k': 0.25,
    'rt': -0.75,
    'rth': -1.23,
    'rn': -0.34,
    'ce': -1.11,
    'st': -0.65,
}
# Frequent spellings whose response is much weaker than their shape suggests.
WEAK_EA = {
    'each': 0.0,
    'year': -0.50,
    'years': -0.20,
    'real': -0.54,
    'team': -0.60,
    'teams': -0.85,
}


def ea_score(word, capital, previous):
    p = word.find('ea')
    if p < 0:
        return 0.0
    if word.endswith('ly') or word.startswith(('search', 'reason', 'weather')):
        return 0.0
    if word in WEAK_EA:
        return WEAK_EA[word] - (0.10 if capital else 0.0)
    if word == 'least':
        return 0.0 if previous == 'at' else -1.15
    if p >= 2:
        return -0.20 if p == 2 else -0.08

    tail = word[p + 2:]
    score = -2.07 if len(word) == 2 else (-0.53 if p == 0 else -0.82)
    if len(tail) == 1:
        score -= 0.49
    elif len(tail) == 2 and tail.endswith('s'):
        score -= 0.21
    elif not tail and p == 1:
        score -= 0.70

    coda, strength = tail, 1.0
    for suffix in ('ing', 'ed', 'er', 's'):
        if coda.endswith(suffix):
            coda = coda[:-len(suffix)]
            strength = 1.0 if suffix == 's' else 0.65
            break
    score += strength * EA_CODAS.get(coda, 0.0)
    if word == 'ear':
        score -= 1.0
    elif word == 'eat':
        score += 1.1
    if p == 1 and word[0] == 'y':
        score += 0.82
    return score - (0.14 if capital else 0.0)


def other_pairs(word):
    score = 0.0
    p = word.find('ee')
    if 0 <= p <= 2:
        tail = word[p + 2:]
        if tail in ('r', 'rs'):
            score -= 0.88
        elif tail in ('p', 'ps') and not word.startswith('k'):
            score -= 0.70
        elif tail in ('t', 'ts'):
            score -= 0.58
        elif word[:p] in ('sh', 'st', 'ch', 'qu'):
            score -= 0.80
        else:
            score -= 0.09
    p = word.find('oa')
    if 0 <= p <= 1:
        score -= 0.25
        if len(word[p + 2:]) == 1:
            score -= 0.47
    elif p == 2:
        score -= 0.08
    p = word.find('eo')
    if 0 <= p <= 1 and len(word) <= 4:
        score -= 0.93
    return score


def step(carry, prefix, upstream):
    words = re.findall('[A-Za-z]+', prefix.token_strings[-1])
    raw = max(words, key=len, default='')
    word = raw.lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = -0.002 + ea_score(word, raw[:1].isupper(), previous)
    value += other_pairs(word)
    return (doc, word), float(value)

"""A spelling-boundary detector: continue an m-ending fragment without a space.

The response is largest for short vowel-leading continuations, particularly
o/u/y. It weakens for longer pieces and common grammatical suffixes. Written
m equivalents in Cyrillic, Greek, Arabic and Thai get analogous rules.
At document boundaries the previous fragment is forgotten. For byte-split
tokens, use the last character of the decoded prefix. These are approximate
spelling rules, not a dictionary of token identities.
"""
import unicodedata as ud

READS = ()
M_LETTERS = 'mMмМμΜمมमਮம'
VOWEL_EQUIVALENTS = str.maketrans('аеёиоуыэюяαειουı', 'aeoiouyeuaaeioui')
SUFFIXES = frozenset('''s es ed ing ings er ers est ly ment ments ent ents
    ation ations al als ous ize izes ized izing isation ization
    able ible ity ities ness ful less'''.split())


def spelling(text):
    return ''.join(c for c in ud.normalize('NFD', text.lower())
                   if not ud.combining(c)).translate(VOWEL_EQUIVALENTS)


def continuation(previous, token):
    m = previous[-1]
    before = max(0, min(len(previous.strip()), 8) - 1)
    if m == 'م':
        if not token[0].isalnum():
            return 0.0
        return max(0.0, 1.30 - 0.15 * (len(token) - 1) - 0.06 * before
                   - 0.28 * (token[-1] in 'من')
                   - 0.42 * (token in ('ات', 'ون', 'ين', 'ية')))
    if m in 'มमਮம':
        # Postposed vowels continue the consonant; Thai tone marks alone do not.
        vowel_sign = token[0] in 'ะาิีึืุูำั' or 'VOWEL SIGN' in ud.name(token[0], '')
        if not vowel_sign:
            return 0.05
        return max(0.05, 2.0 - 0.5 * (len(token) - 1) - 0.1 * before
                   - 0.8 * any(c in '่้๊๋' for c in token))
    if not token[0].isalnum():
        return 0.001
    plain = spelling(token)
    letter = plain[0]
    vowel = letter in 'aeiouy'
    if letter == 'a':
        value = 0.47
    elif letter in 'ei':
        value = 0.81
    elif letter in 'ouy':
        value = 1.18
    elif letter in 'mмμ':
        value = -0.08
    elif letter in 'bdtбдт':
        value = 0.02
    elif letter in 'psnlkпснлк':
        value = 0.27
    elif letter in 'cfgvцфгв':
        value = 0.44
    elif letter in 'hrxwjqхржч':
        value = 0.72
    else:
        value = 0.68
    if token[0].isdigit():
        value = 0.06
    if vowel:
        following = plain[1:2]
        value += (0.62 if not following else 0.40 if following in 'mnмнμν'
                  else 0.63 if following in 'aeiouy' else 0.79)
    else:
        value += 0.35 * (len(token) == 1)
    value -= (0.21 if vowel else 0.02) * max(0, min(len(token), 9) - 2)
    value -= 0.09 * before
    value += 0.27 * m.isupper()
    value += 0.12 * (len(ud.normalize('NFD', token[0])) > 1)
    value -= 0.11 * (m in 'мМ') + 0.68 * (m in 'μΜ')
    value -= 0.33 * (token.lower() in SUFFIXES)
    value -= 0.26 * (token.isupper() and len(token) > 1)
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    # Resolve byte-split characters only when the isolated token is incomplete.
    if '�' in token:
        token = prefix.text_prefixes[-1][-1:]
    previous = carry[1] if carry and carry[0] == document else ''
    value = 0.001
    if previous and previous[-1] in M_LETTERS and token and not token[0].isspace():
        value = continuation(previous, token)
    return (document, token), float(value)

"""Negative responses to lowercase continuations of capital-letter chunks.

The main trigger is a lowercase token immediately after two or more ASCII
capitals: initialism plurals and mixed-case identifiers. Numeric ordinal endings
and several spelled-out ordinals receive smaller negatives. Strength varies with
plural/vowel onset, capital-run length and digits in the current ASCII word.
Non-ASCII or mixed-case continuations receive a weaker response. Other rules
cover internal capital-to-lower transitions and lowercase after digits.
Everything else is zero; document boundaries reset all state.
"""
READS = ()
ORDINAL_ENDINGS = {'th': -0.70, 'st': -0.48, 'nd': -0.54, 'rd': -0.53}
ORDINAL_WORDS = {
    'third': -0.14, 'fourth': -0.21, 'fifth': -0.28,
    'sixth': -0.28, 'seventh': -0.28, 'eighth': -0.28,
    'ninth': -0.28, 'tenth': -0.14,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, capitals_in_word, has_digit = '', 0, False
    else:
        _, previous, capitals_in_word, has_digit = carry
    token = prefix.token_strings[-1]
    tail_capitals = 0
    for char in reversed(previous):
        if not ('A' <= char <= 'Z'):
            break
        tail_capitals += 1
    lower_start = bool(token) and token[0].islower()
    lower_only = token.isascii() and token.isalpha() and token.islower()
    value = ORDINAL_WORDS.get(token.strip().lower(), 0.0)

    if token in ORDINAL_ENDINGS and previous and previous[-1].isdigit():
        value = ORDINAL_ENDINGS[token]
    elif lower_start and tail_capitals >= 2:
        if not lower_only:
            value = -0.7
        elif has_digit:
            value = -1.35
        elif capitals_in_word >= 4 and tail_capitals == 2:
            value = -2.25
        elif token == 's':
            value = -2.1
        elif token[0] in 'aeiou':
            value = -1.95
        else:
            value = -1.75
    elif lower_start and tail_capitals and any('a' <= c <= 'z' for c in previous):
        value = -0.45
    elif lower_only and previous and previous[-1].isdigit():
        value = -0.067

    # Remember case and digits within the uninterrupted ASCII word only.
    for char in token:
        if not (char.isascii() and char.isalnum()):
            capitals_in_word, has_digit = 0, False
        else:
            capitals_in_word += 'A' <= char <= 'Z'
            has_digit = has_digit or char.isdigit()
    return (doc, token, capitals_in_word, has_digit), value

programs.luna:
"""A short text-pattern guess for this component's sparse negative signals.

It marks ordinal endings after a digit, and lowercase continuations immediately
after two or more capitals. These patterns cover ordinals and many mixed-case
names or abbreviation suffixes; all other positions get zero.
"""
READS = ()

ORDINAL_VALUES = {"th": -0.72, "nd": -0.55, "rd": -0.48, "st": -0.48}
ABBREVIATION_SUFFIX = -2.0


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    previous = "" if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0

    if token in ORDINAL_VALUES and previous and previous[-1].isdigit():
        value = ORDINAL_VALUES[token]
    elif token and token[0].islower():
        capitals = 0
        for char in reversed(previous):
            if char.isupper():
                capitals += 1
            else:
                break
        if capitals >= 2:
            value = ABBREVIATION_SUFFIX

    return (document, (previous + token)[-32:]), value

programs.sol:
"""Respond to 'in', with a strong pulse for differences and changes.

Common location, participation, description and use phrases suppress the pulse.
The last word supplies these cues. Case and attached punctuation distinguish
weaker spellings of 'in'; 'within' has a small opposite response. The program
leaves the component's diffuse responses on other tokens unmodeled.
"""
import re

READS = ()
ERROR_OR_DIFFERENCE = set('error errors difference differences mistake mistakes '
                          'exception exceptions discrepancy discrepancies'.split())
CHANGE = set('change changes decrease increases increase reduction shift shifts '
             'improvement improvements variation variations rise decline'.split())
LOCATION_OR_USE = set('located based live lived living stored placed housed situated '
                      'born used use shown presented published interested involved '
                      'engaged participate participating participated employed '
                      'served contained school university'.split())
DESCRIPTION = set('described reported explained discussed recorded written expressed '
                  'included depicted displayed listed founded established built'.split())
MEMBERSHIP = {'role', 'part', 'interest', 'participation'}
EXAMPLE_OR_EXCEPTION = {'as', 'except', 'even', 'when'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    tail = carry[1] if same_document else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([A-Za-z]+)\s*$', tail)
    word = match[1].lower() if match else ''
    value = 0.0
    if token == ' in':
        value = 0.54
        if word in ERROR_OR_DIFFERENCE:
            value = 1.85
        elif word in CHANGE:
            value = 1.45
        elif word in LOCATION_OR_USE:
            value = -0.03
        elif word in MEMBERSHIP:
            value = 0.16
        elif word in DESCRIPTION:
            value = 0.22
        elif word in EXAMPLE_OR_EXCEPTION:
            value = 0.96
        elif word == 'not':
            value = 0.78
        elif word == 'and':
            value = 0.39
        elif word == 'be':
            value = 0.72
        elif not same_document:
            value = 0.66
        elif not word:
            value = 0.47
        elif word.endswith('ed'):
            value = 0.43
    elif token == 'in':
        value = 0.21
    elif re.fullmatch(r'[\s._/(-]*in', token):
        value = 0.30
    elif token.strip() == 'In':
        value = 0.14 if token.startswith(' ') else 0.19
    elif token.strip() == 'IN':
        value = 0.34 if token.startswith(' ') else 0.11
    elif token.strip().lower() == 'within':
        value = -0.22
    return (doc, (tail + token)[-64:]), value

programs.haiku:
READS = ()
CHANGE = {"difference", "differences", "error", "errors", "change", "changes", "increase",
          "increases", "decrease", "decreases", "shift", "reduction", "improvement", "rise",
          "mistake", "variation", "gap", "drop", "growth"}
LOCATIVE = {"located", "used", "use", "shown", "live", "lived", "living", "born", "involved",
            "interested", "based", "published", "presented", "participate", "participated",
            "enrolled", "employed", "housed", "engaged", "included", "interest", "role"}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip().lower() != "in":
        return None, 0.0
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if token != " in":
        return None, 0.2
    if prev in CHANGE:
        return None, 1.5
    if prev in LOCATIVE:
        return None, -0.1
    return None, 0.5

programs.sol:
"""Conversation-control markers, dominated by the end-of-thinking pulse.

The closing thinking marker gets a strong positive pulse, slightly weaker
near the document's beginning. Tool-call closure and tool-response boundaries
have smaller signed pulses. Ordinary text is approximated by a near-zero
background. A conversation start and its initial user label are negative.
"""
import math

READS = ()
TOOL_BOUNDARIES = {
    '<tool_call>': 0.029,
    '</tool_call>': -0.128,
    '<tool_response>': 0.073,
    '</tool_response>': -0.072,
    '<think>': -0.042,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    value = TOOL_BOUNDARIES.get(token, -0.001)
    if token == '</think>':
        value = 1.298 + 0.105 * (1.0 - math.exp(-position / 40.0))
    elif token == '<|im_start|>':
        value = -0.172 if position == 0 else 0.0
    elif token == 'user' and previous == '<|im_start|>':
        value = -0.156 if position == 1 else -0.012
    return (doc, position, token), float(value)

programs.luna:
"""Approximate the marker-related activity at thinking section boundaries.

Harvested high-impact positions consistently carry </think>, with a positive
pulse. The preceding <think> marker has a smaller, mildly negative response.
"""

READS: tuple[str, ...] = ()

MARKER_RESPONSE = {
    "<think>": -0.0536,
    "</think>": 1.3682,
}


def step(carry, prefix, upstream):
    """Return a fixed response for either thinking-section boundary marker."""
    return None, MARKER_RESPONSE.get(prefix.token_strings[-1], 0.0)

programs.sol:
"""A negative response to Hungarian-looking words and recent Hungarian text.

Hungarian function words, suffixes, digraphs and double-acute vowels provide
textual evidence. A decaying language-confidence score makes ordinary Latin
fragments respond too. English mentions of Hungary/Budapest are recognized
without setting that score; Finnish names get a weaker response. This compact
heuristic omits finer distinctions between individual pieces. All context
cues reset when the document changes.
"""
import unicodedata
from functools import lru_cache

READS = ()
CUES = set('egy vagy hogy csak és még már lehet magyar szer elő'.split())

# Grammar groups: ordinary response, additional response in Hungarian context.
WORDS = (
    ('egy', -4.7, -1.0),                       # indefinite article
    ('vagy hogy lehet csak', -3.3, -1.4),       # connectives / possibility
    ('és még már', -2.7, -1.5),                # coordination / time / degree
    # Ambiguous particles, negation, articles, demonstratives and verbs:
    ('meg nem az ez azt ezt volt tud kell lesz fog', -0.4, -4.0),
    ('hely szer elő köz magyar jel', -2.1, -2.3),  # common Hungarian roots
)
SUFFIXES = (
    ('ban ben nak nek ból ből ról ről tól től hoz hez höz nál nél val vel '
     'ok ek ak ök ott ett tt ja je juk jük unk ünk', -0.1, -3.4),
    ('ás és ág ég ság ség ít', -0.1, -4.5),      # nominal / verbal derivation
    ('ász ész', -3.8, -0.2),                   # occupations
    ('ány ény', -1.7, -2.3),                   # nominal endings
)


@lru_cache(maxsize=32768)
def features(token):
    word = token.strip().lower()
    latin = bool(word) and all(c.isalpha() and 'LATIN' in unicodedata.name(c, '')
                               for c in word)
    starts = bool(token) and (token[0].isspace() or token[0].isupper())
    accent = latin and any(c in word for c in 'áéíóöúü')
    digraph = latin and any(d in word for d in ('gy', 'sz', 'cs', 'zs'))
    double = latin and any(c in word for c in 'őű')
    cue = 1.0 if double else 0.9 if starts and word in CUES else 0.0
    shared = token[:1].isspace() and word in {'az', 'meg', 'nem'}
    response = (0.0, 0.0)
    if word.startswith('hungar'):
        response = (-4.5, -0.8)
    elif word == 'budapest':
        response = (-5.9, -1.2)
    elif word in {'finnish', 'finland', 'helsinki'}:
        response = (-0.6, 0.0)
    elif word == '.hu':
        response = (-3.1, -1.0)
    elif word in {'-as', '-es', '-os', '-ös'}:
        response = (-0.3, -2.6)
    elif latin:
        response = (0.0, -0.8 if starts else -1.0 if len(word) >= 4 else -1.6)
        if double:
            response = (-3.0, -0.5)
        else:
            groups = WORDS if starts else SUFFIXES
            for group, ordinary, contextual in groups:
                if word in group.split():
                    response = (ordinary, contextual)
                    break
            else:
                if not starts and accent:
                    response = (0.0, -3.1)
                elif len(word) <= 4 and any(d in word for d in ('gy', 'sz')):
                    response = (-0.6, -4.1)
                elif len(word) <= 4 and any(d in word for d in ('cs', 'zs')):
                    response = (-0.2, -4.2)
                elif len(word) <= 4 and any(d in word for d in ('ny', 'ly')):
                    response = (0.0, -3.2)
                elif not starts and 'z' in word:
                    response = (0.0, -3.7)
    return response, cue, shared, accent, digraph


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    strong, vowels, digraphs = (0.0, 0.0, 0.0)
    if carry is not None and carry[0] == doc:
        strong, vowels, digraphs = carry[1:]
    confidence = max(strong, vowels * digraphs)
    token = prefix.token_strings[-1]
    (ordinary, contextual), cue, shared, accent, digraph = features(token)
    # Account for language names split into two pieces, e.g. Mag + yar.
    if prefix.position and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2]
        if previous[-1:].isalpha() and token[:1].isalpha():
            joined = (previous + token).strip().lower()
            if joined.startswith('hungar'):
                ordinary, contextual = -4.5, -0.8
            elif joined == 'magyar':
                ordinary, contextual = -4.0, 0.0
    value = ordinary + contextual * confidence
    strong = min(1.0, max(strong * 0.985, cue) + 0.3 * shared)
    vowels = min(1.0, vowels * 0.96 + 0.35 * accent)
    digraphs = min(1.0, digraphs * 0.96 + 0.5 * digraph)
    return (doc, strong, vowels, digraphs), float(value)

"""Lexical putting/placement signal, strongest on 'put', 'puts', 'putting'.

Smaller responses cover the listed placement, throwing, retaining, assigning,
and writing words, some East Asian action/construction tokens, and tool calls.
Whitespace, case, and method-name punctuation affect the calibrated strength.
One-token memory captures objects/particles after 'put' and the 'take place'
idiom; it resets at document boundaries. Unlisted tokens otherwise predict zero.
This approximates lexical selectivity, not the meaning of every sentence.
