READS = ()

# Related actions and their inflections, grouped by training response strength.
ACTION_GROUPS = (
    (1.4, 'throw throwing threw submit'),
    (1.1, 'throws thrown shut invest investing placing pushing submitting pitcher'),
    (0.9, 'push pushes pushed investments placement exert lays'),
    (0.85, 'sets'),
    (0.8, 'call cast casts keep keeps keeping kept investment invested insert pouring'),
    (0.7, 'calls calling pours pitching'),
    (0.65, 'set placed send'),
    (0.6, 'places committing'),
    (0.5, 'add adds adding sent sending setting write commit poured submitted'),
    (0.35, 'place writing laid'),
    (0.3, 'lay pour pitch plunge'),
    (0.2, 'called committed'),
)
ACTIONS = {w: v for v, words in ACTION_GROUPS for w in words.split()}
EAST_ASIAN = {
    '投': 3.65, '投入': 3.05, '投放': 2.9, '抛': 3.0, '拋': 3.0,
    '推': 1.6, '吐': 1.6, '把': 1.15, '将': 0.73, '將': 0.73,
    '打': 0.76, '放': 0.67, '投资': 0.85, '投資': 0.85, 'すると': 0.83,
}

# Immediate object/particle after a putting word; not a persistent topic state.
OBJECT_GROUPS = (
    (1.7, 'it'), (1.8, 'an'), (1.1, 'a'), (0.9, 'the my our your his their'),
    (0.65, 'him her them me us you'), (0.57, 'on out'),
    (0.3, 'in into'), (-0.11, 'up'),
)
AFTER_PUT = {w: v for v, words in OBJECT_GROUPS for w in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    bare = s.lstrip(' \t\r\n._/(\\')
    word = bare.lower()
    if word in ('put', 'puts', 'putting'):
        if s[:1].isspace():
            value = {'put': 6.95, 'puts': 6.2, 'putting': 6.55}[word]
        elif s.startswith(('.', '_')):
            value = 6.1 if s.islower() else 4.1
        else:
            value = 5.9 if s[:1].isupper() else 4.7
    elif (word.startswith('put') and word[3:].isalpha()
          and s.startswith(('.', '_')) and bare[3:4].isupper()):
        value = 3.3  # CamelCase putSomething methods.
    elif s in ('<tool_call>', '</tool_call>'):
        value = 1.05 if s == '<tool_call>' else 0.24
    else:
        value = EAST_ASIAN.get(s, ACTIONS.get(word, 0.0))

    if word in ('place', 'write', 'pour') and bare[:1].isupper():
        value = {'place': 0.74, 'write': 0.72, 'pour': 0.75}[word]
    if word == 'set' and s.strip() == 'SET':
        value = 1.0
    if word == 'add' and s.startswith('.'):
        value = 0.98 if bare[:1].isupper() else 0.3
    if word == 'place' and previous in ('take', 'takes', 'took', 'taking'):
        value = -0.12
    if previous in ('put', 'puts', 'putting'):
        if s[:1].isspace():
            value += AFTER_PUT.get(word, 0.1)
        elif s.isalpha():
            value += 0.8  # Continuation of the lexical stem, e.g. put-ative.
    return (doc, word), float(value)

