"""Verbs of putting and placing.

The unit is a whole word token. The strongest response is to "put" (and "putting",
"puts"): about 7 when the word is spaced or capitalised, about 5 when it is glued
on (as in "put" after a dot). Weaker responses (about 0.3 to 1.5) go to other verbs
that set something down, insert, push, pour, throw, keep or send an object somewhere,
and to their Chinese, Japanese and Vietnamese counterparts. Everything else is ~0.
"""
READS = ()

PUT = {"put", "putting", "puts"}
PLACE = {
    "set", "sets", "setting", "place", "places", "placed", "placing",
    "insert", "inserted", "inserting", "push", "pushed", "pushes", "pushing",
    "pour", "pouring", "throw", "throwing", "add", "adding", "keep", "keeps",
    "kept", "keeping", "send", "sent", "submit", "call", "calls", "calling",
    "cast", "invest", "investing",
}
FOREIGN = {"投": 3.5, "投入": 3.5, "推": 1.6, "把": 1.1, "要把": 1.1, "将": 0.7,
           "放": 0.6, "đưa": 1.4, "đẩy": 1.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower().strip(".")
    if word in PUT:
        return None, 7.0 if tok[:1] == " " or tok[:1].isupper() else 5.3
    if tok == "<tool_call>":
        return None, 1.0
    if word in PLACE:
        return None, 0.7
    if word in FOREIGN:
        return None, FOREIGN[word]
    return None, 0.0

programs.sol:
"""Sparse lexical approximation of plans, schedules, and project milestones.

Several planning forms have negative responses; their following `to` or
`for` is more negative. Related Chinese planning, launch, and completion
words are included. Relative-time and placement cues have weaker responses.
`live` is a separate lexical trigger, especially in `MTV Live`.
The phrase `good idea` has the opposite sign. Everything else is zero.
The previous token and a short text tail are remembered within each document.
"""

READS = ()

PLANNING_FORMS = {
    'plans', 'planned', 'scheduled', 'aims', 'aiming', 'intends', 'intended',
}
DESIGN_FORMS = {'concept', 'conception', 'conceived'}
COMPLETION_FORMS = {'ready', 'completed', 'completion'}
LAUNCH_FORMS = {'debut', 'launch', 'launched', 'launching', 'unveiled'}
RELATIVE_TIME = {'first', 'last', 'again', 'later', 'initially', 'originally'}
RECURRENCE = {'often', 'sometimes'}
PLAN_LINKS = {'plan', 'planning', 'intend', 'intended', 'intention'}
EXPECTATION_LINKS = {'expected', 'estimated', 'supposed', 'hopes', 'hoping'}

CHINESE_PLANS = {'计划', '計畫', '估计', '预期', '打算'}
CHINESE_LAUNCH = {'上线', '通车', '发售'}
CHINESE_COMPLETION = {'完工', '建成', '交付'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if word in PLANNING_FORMS:
        value = -0.23
    elif word in DESIGN_FORMS or word in COMPLETION_FORMS:
        value = -0.16
    elif word in LAUNCH_FORMS:
        value = -0.13
    elif word in RELATIVE_TIME:
        value = -0.06
    elif word in RECURRENCE or word in {'below', 'further'}:
        value = -0.10
    elif word == 'above':
        value = -0.07
    elif word == 'idea':
        value = 0.39 if previous == 'good' else -0.08
    elif word == 'live':
        value = -0.60 if tail.rstrip().endswith('MTV') else -0.22

    if word in {'to', 'for'}:
        if previous in {'scheduled', 'slated', 'intends'}:
            value = -0.66 if word == 'to' else -0.53
        elif previous in {'plans', 'planned'}:
            value = -0.48 if word == 'to' else -0.42
        elif previous in PLAN_LINKS:
            value = -0.33 if word == 'to' else -0.29
        elif previous in {'aims', 'aiming', 'projected'}:
            value = -0.40
        elif word == 'to' and previous in EXPECTATION_LINKS:
            value = -0.26
        elif previous in {'aim', 'designed'}:
            value = -0.20
    elif word == 'plans' and previous in {'announced', 'future', 'released'}:
        value = -0.55
    elif word == 'planned' and previous in {'originally', 'initially'}:
        value = -0.55
    elif word == 'completed' and previous == 'command':
        value = -0.08

    if token in CHINESE_PLANS:
        value = -0.16
    elif token in CHINESE_LAUNCH:
        value = -0.30
    elif token in CHINESE_COMPLETION:
        value = -0.43
    elif token in {'预计', '试'}:
        value = -0.33
    elif token == '投产':
        value = -0.65
    elif token == '試':
        value = -0.15
    elif token == '計' and tail.endswith('預'):
        value = -0.44

    return (doc, word, (tail + token)[-24:]), float(value)

