    "delivery", "launch", "ready", "concept", "projected", "conceived",
}
BUSINESS_CONTEXT = {
    "investors", "financial", "budget", "commercial", "customers",
}


def step(carry, prefix, upstream):
    """Use recent wording to mark intended actions and a small set of project milestones."""
    here = prefix.token_strings[-1].strip().casefold()
