programs.sol:
"""Approximate a negative response to unfinished Unicode characters, strongest
in Chinese/Japanese text. Recent complete characters identify the likely script.
Document-opening Markdown/title/chat markers and tool delimiters have separate
responses. Other text stays near zero. No later character is inspected.
"""
READS = ()
OPENERS = {'#': 1.43, '##': 0.432, 'Title': 0.864, '<|im_start|>': 0.339}
DELIMITERS = {
    '<tool_call>': -0.142, '</tool_call>': -0.056,
    '<tool_response>': 0.146, '</tool_response>': -0.075,
    '<|im_end|>': 0.058,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = 0.001
    if first and token in OPENERS:
        value = OPENERS[token]
    elif token in DELIMITERS:
        value = DELIMITERS[token]
    elif token.endswith('\ufffd'):
        # A completed literal U+FFFD is not an unfinished character. This is
        # its tokenizer spelling, not a learned exception for an arbitrary word.
        if prefix.token_ids[-1] == 5691:
            value = -0.016
        elif prefix.text_prefixes[-1].endswith('\ufffd'):
            codes = [ord(c) for c in recent]
            kana = sum(0x3040 <= n <= 0x30ff for n in codes) >= 2
            cjk = sum(0x4e00 <= n <= 0x9fff for n in codes) >= 2
            hangul = sum(0xac00 <= n <= 0xd7a3 for n in codes) >= 2
            cyrillic = any(0x400 <= n <= 0x52f for n in codes)
            # The tokenizer's first 256 entries are single-byte fallbacks.
            if prefix.token_ids[-1] < 256:
                value = -0.06
            elif token == '\ufffd':
                if kana:
                    value = -0.83
                elif cjk:
                    value = -0.70
                else:
                    value = -0.17 if hangul else -0.15
            elif token == ' \ufffd':
                value = -0.33 if hangul else 0.005 if cjk or kana else -0.10
            else:
                if cyrillic:
                    value = -0.40
                else:
                    value = -0.03 if cjk or kana else -0.06
    recent = (recent + token.replace('\ufffd', ''))[-50:]
    return (doc, recent), value

programs.luna:
"""Recognize malformed UTF-8 endings and heading markers."""
READS = ()
SCALE = 2.0

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "�" in token and prefix.text_prefixes[-1].endswith("�"):
        return None, -0.12 * SCALE
    if token in {"#", "##"}:
        previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        if previous == "<|endoftext|>":
            return None, (0.18 if token == "#" else 0.06) * SCALE
    return None, 0.0

programs.sol:
"""Predict an e-initial continuation feature from spelling.

An e followed by a familiar compound root is strongly negative. Other bare
e-consonant-vowel fragments respond more weakly, especially after an
consonant-only ending of the previous token. Inflectional endings and
isolated letters are weak. Constants approximate training category averages.
Context resets at document boundaries.
"""
import re
import unicodedata

READS = ()
VOWELS = frozenset('aeiouy')
NOUNS = frozenset('''
line land time water wire world work way wood stone book room house
man men woman women boy girl life side end name space place day night
light log map list file pad bin data wear width style mark tag delta
'''.split())
WORDS = NOUNS | frozenset('''
lay select set get put run call read write make take give load stop move
start show use help test find change long main
com lib min max ref ptr cmd init
'''.split())
ENDINGS = frozenset('''
ed er es en ers ens ent ents est ern ess ence ences ency etic etics
etal eral eter eters ening ering elling ely
'''.split())


def response(token, previous):
    s = ''.join(c for c in unicodedata.normalize('NFD', token)
                if not unicodedata.combining(c)).lower()
    if not s.startswith('e') or not s.isalpha():
        return 0.0
    match = re.search(r'[a-zA-Z]+$', previous)
    stem = match[0].lower() if match else ''
    onset = bool(stem) and all(c not in VOWELS for c in stem)
    if len(s) == 1:
        return 0.0 if not stem else 0.015
    if len(s) == 2:
        return -0.03 if onset else (0.03 if stem else -0.02)
    root = s[1:]
    if root in WORDS or root.removesuffix('s') in NOUNS:
        if onset:
            return -0.70
        return -0.49 if 0 < len(stem) <= 2 else -0.39
    if token.isupper():
        return -0.17 if onset else (-0.07 if not stem else 0.0)
    if s in ENDINGS:
        return -0.07 if onset else 0.01
    if s[1] not in VOWELS and s[2] in VOWELS:
        if len(s) == 3:
            return -0.12 if onset else (-0.07 if not stem else 0.01)
        if len(s) == 4:
            return -0.22 if onset else -0.06
        return -0.14 if onset else -0.04
    return -0.06 if onset else (-0.03 if not stem else 0.005)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

