programs.sol:
"""Standalone spacing, especially the first digit of a padded number.

Repeated spaces raise the prediction at a separate one-space token and
at a digit following that token. Line-start padding is stronger than mid-line padding;
longer whitespace tokens dilute the effect. A number after punctuation plus a
space responds modestly, unlike one after a word or another digit. Smaller
responses cover other tokens after an unmerged space. These are text-formatting
rules, not a detector of numbers everywhere.
"""
from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, before, spaces, line = ('', '', 0, True) if first else carry[1:]
    token = prefix.token_strings[-1]
    digit = len(token) == 1 and token in '0123456789'
    value = 0.0

    if token == ' ':
        if first:
            value = 2.4
        elif spaces:
            n = len(previous)
            if n == 1:
                value = 1.05 + 1.4 * line
            else:
                value = min(1.04, 1.6 / sqrt(n))
            if n > 1 and not line:
                value *= 0.5
    elif digit and previous == ' ':
        if spaces >= 2:
            n = len(before)
            if n == 1:
                value = 3.2 + 0.85 * line
            elif n <= 3:
                value = 3.5 - 0.25 * n - 0.5 * (not line)
            else:
                value = 1.3 + 3 / n**0.75 - 0.3 * (not line)
            value -= 0.07 * max(0, int(token) - 1)
        elif line:
            value = 2.5
        elif before and before[-1].isalnum():
            value = 0.0
        else:
            value = 0.7
    elif previous == ' ' and token and not digit:
        if token.isspace() and '\n' not in token:
            value = 1.05 + 1.4 * line
        elif token.startswith(' '):
            if token.strip().isalpha():
                value = 0.45 * line
            else:
                value = 0.3 + 0.4 * line
        else:
            value = 0.3 if token.isalpha() else 0.6

    if token and not token.strip(' '):
        spaces += len(token)
    else:
        spaces = 0
        line = token.endswith('\n')
    return (doc, token, previous, spaces, line), float(value)

