    return None, 0.0

programs.sol:
"""An orthographic approximation: negative on u-initial word fragments.

This includes Latin u/U and Cyrillic у, after stripping spaces/apostrophes.

Spaces, capitals, familiar words and common grammatical pieces usually
weaken it. Consonant digraphs and u-m-vowel syllables strengthen it. The
technical names UTF, uint, URI/UID/UUID and UTC are particularly strong.
Only single letters use context, to distinguish free u from continued u.
All other tokens get a near-zero baseline.
"""

READS = ()

COMMON_WORDS = frozenset('''
up use uses used using useful user users username usernames
under until upon unless upper update updates updated updating
unknown unable understand understanding understood undefined
unit units united union university undo urban utility utilities
'''.split())
GRAMMATICAL_PIECES = frozenset('und ung ungen ure ures urs ues'.split())


def response(token, continuation):
    word = token.lstrip(" \t\n\r'’")
    if not word:
        return 0.0005
    spaced = word != token
    if word.startswith('у'):
        if len(word) == 1:
            return -0.015
        strong = word[1] in 'бчшхй' or word.startswith('уст')
        return -0.59 if strong else -0.24
    if word[0] not in 'uU':
        return 0.0005
    lower = word.lower()
    if lower.startswith('utf'):
        return -1.11
    if lower.startswith('uint'):
        return -0.64
    if lower in ('uri', 'uid', 'uuid', 'utc'):
        return -0.56
    if lower == 'un':
        return 0.11 if word[0] == 'U' else 0.064
    if lower in GRAMMATICAL_PIECES:
        return 0.02 if lower.startswith(('und', 'ung')) else -0.053
    if len(word) == 1:
        return 0.055 if spaced or not continuation else -0.073
    if lower in ('usual', 'usually', 'unique', 'uniform'):
        return -0.22
    if lower in COMMON_WORDS:
        if spaced:
            return -0.01
        return -0.17 if lower in ('use', 'uses', 'used', 'using') else -0.064
    if spaced:
        return -0.11
    if word[0] == 'U':
        return -0.15
    if lower.startswith(('uch', 'ush', 'ugh', 'usch')):
        return -0.70
    if len(word) in (3, 4) and word[1] == 'm' and word[2] in 'aeiou':
        return -0.71
    if len(word) == 2:
        if word[1] in 'bcfhjvyß':
            return -0.48
        return -0.20 if word[1] in 'dkpz' else -0.06
    if len(word) >= 5:
        return -0.25
    return -0.46 if word[1] in 'bcdfhijkmtz' else -0.30


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    continuation = (carry is not None and carry[0] == doc
                    and carry[1].isalpha())
    value = response(token, continuation)
    return (doc, token[-1:] or ' '), float(value)

"""Negative boundary/obstruction words and negative separation phrases.
Some opening phrases are positive ('open set', 'opening day'), but 'open up'
and 'cut off' are negative. Recognize split words and reset at document changes.
Two coding phrases also give positive values. Other vocabulary stays near zero.
"""
READS = ()


def word_values(groups):
    return {w: v for words, v in groups for w in words.split()}


BOUNDARIES = word_values((
    ('boundary boundaries barrier barriers firewall firewalls', -1.6),
    ('wall walls', -1.2),
    ('border borders gateway gateways', -0.8),
    ('fence fences tunnel tunnels', -0.55),
    ('gate gates bridge bridges', -0.3),
    ('insulation isolation protection privacy', -0.4),
    ('partition partitions separation distinction threshold bound bounds', -0.24),
    ('closed 闭 閉 关', -0.25),
    # Chinese wall, barrier, boundary, and passage terms.
    ('墙 牆 界限 屏障 围墙', -1.6),
    ('隔 隔离 壁 墙体', -0.95),
    ('界 隧道 桥梁 桥 墙面', -0.6),
))
OPEN = set('open opens opened opening'.split())
CLOSE = set('close closes closed closing shut shuts'.split())
CUT = set('cut cuts cutting'.split())
DIVIDE = set('divide divides divided dividing split splits splitting'.split())
START = set('start starts started starting'.split())
HARD = set('boundary boundaries barrier barriers border borders'.split())
FILLER = set('it them himself herself the a an his her its their'.split())
OPEN_PHRASES = word_values((
    ('up', -1.6), ('to out off', -0.65), ('of', -0.25),
    ('door doors connection channels communication', -1.0),
    ('in on at with', 0.6),
    ('subset subsets set sets', 2.0),
    ('plan arms hands letter position day hours', 1.2),
    ('ai source file status night tomorrow', 0.6),
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = older = tail = ''
        position, divide_age = 0, 99
    else:
        _, previous, older, tail, position, divide_age = carry
        position, divide_age = position + 1, divide_age + 1
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('_-').lower()
    joined = tail + word if raw[:1].isascii() and raw[:1].isalpha() else word
    completed = joined != word and joined in BOUNDARIES
    if joined in BOUNDARIES:
        word = joined
    value = BOUNDARIES.get(
        word, {'between': -0.14, 'off': -0.13}.get(word, 0.0))
    if completed and joined.startswith('gateway'):
        value *= 1.8
    if raw.strip()[:1].isupper():
        value *= 0.85
    if joined != word and joined.endswith(('wall', 'walls')):
        value = -0.9
    elif joined != word and joined.startswith('gatekeep'):
        value = -1.2
    tail = joined[-24:] if raw[-1:].isascii() and raw[-1:].isalpha() else ''

    if word == 'between':
        if previous in HARD:
            value = -1.8
        elif previous in {'bridge', 'bridges', 'interface', 'divide', 'line'}:
            value = -1.1
        elif previous in {'gap', 'gaps', 'space', 'interval',
                           'edges', 'middle', 'halfway'}:
            value = -0.6
        elif previous in {'distance', 'distances', 'difference', 'differences'}:
            value = -0.3
    if previous in HARD:
        value = {'of': -1.0, 'line': -1.4, 'lines': -1.4,
                 'condition': -0.75, 'conditions': -0.75,
                 'value': -0.75, 'values': -0.75}.get(word, value)
        if word == 'to':
            value = -1.0 if previous.startswith('barrier') else -0.6
    elif previous in {'wall', 'walls'} and word == 'of':
        value = -0.45
    opening = previous in OPEN or (previous in FILLER and older in OPEN)
    closing = previous in CLOSE or (previous in FILLER and older in CLOSE)
    if opening:
        value = OPEN_PHRASES.get(word, value)
    elif closing and word in {'door', 'doors', 'connection'}:
        value = -0.9
    if previous in CLOSE and word in {'on', 'in', 'set', 'sets'}:
        value = 0.7
    if word == 'off' and previous in CUT | CLOSE | {'sealed', 'switching'}:
        value = -1.05
    if previous in CUT and word in {'out', 'from', 'through'}:
        value = -0.5
    if previous in {'break', 'breaking', 'broken', 'broke'} and word in {'up', 'off'}:
        value = -0.7
    if previous in START and word in {'up', 'out', 'from', 'off'}:
        value = -0.7 if word == 'off' else -0.4
    if word in DIVIDE:
        divide_age = 0
    elif word == 'into' and (divide_age <= 8 or previous in CUT):
        value, divide_age = -0.65, 99
    elif any(c in raw for c in '.;!?\n'):
        divide_age = 99

    # Two secondary, positive coding phrases.
    if word == 'code' and previous == 'exit':
        value = 0.27
    if word == 'modules' and raw.startswith('_') and previous in {'node', '/node'}:
        value = 0.31
    if position == 0:
        if word in {'gate', 'gates', 'border', 'borders'}:
            value = -2.1
        elif word in {'boundary', 'boundaries', 'barrier', 'barriers'}:
            value = -3.4
        elif value < -0.4:
            value *= 1.55
        elif word in {'open', 'between'}:
            value = -0.67
    return (doc, word, previous, tail, position, divide_age), float(value)

programs.luna:
"""Make a conservative lexical guess for this sparse activation.

Boundary, barrier, wall, and related words get a small negative value, as do
"between" and a few opening-related forms. A few fixed nearby phrases get a
small positive value. Exact token-string checks miss split words and most
contextual variation; every guess is damped to avoid overpredicting.
"""
READS = ()

BOUNDARIES = {
    "boundary", "boundaries", "border", "borders", "barrier", "barriers",
    "wall", "walls", "firewall", "gate", "gates", "edge", "edges",
    "fence", "fences", "breakwater", "breakwaters", "separation",
    "partition", "partitions", "divide", "divides", "dividing",
    "demarcation", "threshold", "borderline",
}


def clean(token):
    return token.strip().lower().strip(".,!?;:()[]{}\"'`*_#")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    word = clean(prefix.token_strings[-1])
    recent = set(history[-6:])

    value = 0.0
    if word in BOUNDARIES:
        value = -1.0
    elif word == "between":
        value = -0.55
    elif word in {"open", "opening"}:
        value = -0.65
    elif word == "up" and recent.intersection(
        {"open", "opening", "start", "starts", "started", "begun"}
    ):
        value = -1.0
    elif word == "off" and recent.intersection({"start", "starts", "started"}):
        value = -0.65
    elif word == "day" and "opening" in recent:
        value = 1.2
    elif word == "cover" and "open" in recent:
        value = 0.7
    elif word == "ai" and "open" in recent:
        value = 0.6
    elif word == "hands" and "open" in recent:
        value = 1.0
    elif word in {"界", "狱"}:
        value = -0.7

    history = (history + (word,))[-8:]
    return (doc, history), value * 0.3

programs.sol:
"""Lexical 'to/through' detector, weakened in familiar grammatical phrases.

A 'to' token is positive by default, weak after words commonly taking a
to-complement, and strongly negative after a copular 'be'. Several other
predicate starters also turn negative after 'be'. Most tokens are zero.
Only the trailing 48 characters of the current document are remembered.
"""
import re

READS = ()

# Common words followed by infinitival or prepositional 'to'.
TO_COMPLEMENTS = set('''
need want try attempt begin continue start decide choose agree refuse fail
manage learn expect seem tend have mean suppose allow force ask invite
lead contribute respond refer relate belong happen add apply correspond
connect link attach commit dedicate entitle prepare hope prefer know
ready easy hard difficult impossible necessary important possible sure
happy free enough best better willing likely able unable ability
attention access approach way order chance opportunity effort desire
decision failure right plans potential solution answer response reference
according due prior pursuant next close adjacent relative related compared
comparison contrast equal equivalent proportional parallel perpendicular
opposed bound respect relation addition subject limited sensitive designed
intended shown similar like
'''.split())
STRONG_TO = set('able unable willing ability wish likely equal'.split())
MOTION = set('''
go come get move return send turn use make find give provide
'''.split())
IRREGULAR = {'had': 'have', 'has': 'have', 'began': 'begin', 'meant': 'mean',
             'led': 'lead', 'known': 'know', 'went': 'go', 'came': 'come',
             'got': 'get', 'sent': 'send', 'made': 'make', 'found': 'find',
             'given': 'give'}
BE = {'is': 1.0, 'was': 0.8, 'be': 0.65, 'are': 0.6,
      'were': 0.65, 'been': 0.55}
PREDICATES = (
    (-2.15, {'to'}),
    (-1.75, {'that'}),
    (-0.9, {'when', 'if', 'whether', 'for'}),
    (-0.55, {'in', 'at', 'by'}),
    (-0.6, {'equal', 'true', 'done', 'made', 'provided', 'achieved', 'reached'}),
    (-0.3, {'with', 'as', 'because', 'found', 'given', 'no', 'this', 'it'}),
    (-0.13, {'the', 'of', 'on'}),
    (0.22, {'also', 'still', 'originally', 'highly', 'widely'}),
)


def bases(word):
    """Allow common English inflections of entries in the word classes."""
    out = {word, IRREGULAR.get(word, word)}
    for ending in ('s', 'es', 'ed', 'ing'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            out.update((stem, stem + 'e'))
            if stem.endswith('i'):
                out.add(stem[:-1] + 'y')
            if len(stem) > 1 and stem[-1] == stem[-2]:
                out.add(stem[:-1])
    return out


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    match = re.search(r'([A-Za-z]+|\d+)$', tail.rstrip())
    prev = match.group().lower() if match else ''
    roots = bases(prev)
    spelling = raw.strip().lstrip('_-.(["“')
    value = 0.0
    if spelling.lower() == 'to':
        value = 0.93
        if roots & TO_COMPLEMENTS or prev in {
            'how', 'only', 'just', 'about'
        }:
            value = 0.0
        if prev in STRONG_TO:
            value = -0.45
        if prev in {'need', 'want', 'not'}:
            value = -0.2
        if prev == 'as':
            value = -0.3
        if roots & MOTION:
            value = 0.4
        if prev in {'it', 'you', 'me', 'us', 'him', 'her', 'them'}:
            value = 0.55
        if prev in {
            'up', 'down', 'out', 'back', 'on', 'off', 'over', 'time'
        }:
            value = 0.8
        if prev.isdigit():
            value = 1.6
        if not match:
            value = 1.4 if tail else 1.8
        if raw.strip() != 'to':
            value = 1.1
        if spelling == 'To':
            joined = not raw[:1].isspace() and tail[-1:].isalpha()
            value = 1.15 if joined else 1.7
            if raw[:1].isspace():
                value = 1.4
        if spelling.isupper():
            value = 0.85
    elif spelling.lower() in {'through', 'thru'}:
        value = 0.72 if roots & {'pass', 'go', 'loop', 'flow'} else 0.97
    elif word in {'equal', 'done', 'made', 'provided', 'true', 'achieved'}:
        value = -0.08
    if prev in BE:
        for correction, starters in PREDICATES:
            if word in starters:
                value = correction * BE[prev]
                break
        else:
            if raw.startswith((',', ':')):
                value = -0.6 * BE[prev]
            elif raw.isspace():
                value = -0.15 * BE[prev]
    return (doc, (tail + raw)[-48:]), float(value)

