programs.sol:
"""Approximate English verb-complement responses and chat boundaries.

Common phrasal verbs and light-verb idioms get positive pulses on their
completions (set up, make sense, take place). An intervening object often
strengthens the pulse. Unrecognized particles get a smaller baseline.
A few prepositional continuations and chat markers have separate rules.
Hyphenated particles are weaker; fused continuations of make, put, go,
and look are sometimes suppressed. Everything else is predicted near zero.
The four-token memory resets at each document boundary.
"""
READS = ()

# Verb particles, with a few especially strong or weak constructions.
PHRASAL = {
    'up': 'set bring make take hold put give pick come add keep wrap look '
          'show catch turn clean get end go fill split grow wake open hook '
          'sign speed clear mess break pull pay',
    'out': 'check find figure set point take work make come put write fill '
           'leave cut cancel stand turn print carry bring lay pay hold pull '
           'spread flush hand reach',
    'down': 'take bring put shut break sit write come set look cut hold '
            'let lay pull move',
    'off': 'take put set cut turn pull break leave throw',
    'back': 'bring put come give take get pay',
    'together': 'put bring come work hold add take join combine gather '
                'multiply thread group pull',
    'away': 'take put give pass keep',
    'forth': 'set put', 'aside': 'set put', 'apart': 'take pull set',
    'forward': 'put look bring pay',
}
PHRASAL = {word: set(verbs.split()) for word, verbs in PHRASAL.items()}
PARTICLE_BASE = {
    'up': 0.65, 'out': 0.6, 'down': 0.6, 'off': 0.6, 'back': 0.35,
    'together': 0.7, 'away': 0.65, 'forth': 1.0, 'aside': 0.8,
    'apart': 0.65, 'forward': 0.5,
}
UP_STRONG = {'set': 1.25, 'bring': 1.2, 'make': 1.05, 'take': 0.95,
             'hold': 0.85, 'put': 0.85, 'give': 0.8, 'pick': 0.75,
             'come': 0.75, 'add': 0.75, 'get': 0.35, 'end': 0.3, 'go': 0.25}
NOUN_COMPLEMENTS = {
    'make': 'sense sure clear possible easy easier difficult mistake '
            'difference way decision feel aware contribution choices '
            'changes choice change error errors decisions attempt case look',
    'take': 'place advantage care look account consideration time action',
    'play': 'role roles', 'pay': 'attention',
    'ask': 'question questions', 'answer': 'question questions',
    'get': 'chance rid attention', 'spend': 'time',
    'raise': 'question questions', 'find': 'way',
    'give': 'chance opportunity rise', 'keep': 'alive simple mind',
    'set': 'equal', 'call': 'attention', 'catch': 'attention',
    'bring': 'attention', 'draw': 'line attention',
}
NOUN_COMPLEMENTS = {v: set(ws.split()) for v, ws in NOUN_COMPLEMENTS.items()}
NOUN_BASE = {
    'sense': 0.9, 'sure': 0.42, 'clear': 0.65, 'possible': 0.25,
    'easy': 0.15, 'easier': 0.0, 'difficult': -0.15, 'mistake': 0.25,
    'difference': 0.15, 'way': 0.4, 'decision': -0.05, 'feel': -0.05,
    'place': 0.55, 'advantage': 0.6, 'care': 0.45, 'look': 0.2,
    'account': 0.6, 'consideration': 0.2, 'time': -0.2,
    'role': 0.75, 'roles': 0.5, 'attention': 0.6,
    'question': 0.2, 'questions': 0.2, 'chance': 0.15, 'rid': 0.4,
    'rise': 0.35, 'alive': 0.25, 'simple': 0.05, 'mind': -0.35,
    'equal': 0.35, 'line': 0.3,
}
ROOTS = set(NOUN_COMPLEMENTS) | {'thank'}
for verbs in PHRASAL.values():
    ROOTS.update(verbs)
IRREGULAR = {
    'took': 'take', 'taken': 'take', 'made': 'make', 'brought': 'bring',
    'came': 'come', 'given': 'give', 'gave': 'give', 'went': 'go',
    'gone': 'go', 'got': 'get', 'gotten': 'get', 'kept': 'keep',
    'held': 'hold', 'found': 'find', 'left': 'leave', 'written': 'write',
    'wrote': 'write', 'sat': 'sit', 'paid': 'pay', 'broke': 'break',
    'broken': 'break', 'laid': 'lay', 'caught': 'catch', 'grew': 'grow',
    'woken': 'wake', 'drew': 'draw', 'drawn': 'draw',
}
OBJECTS = set('it him her them you us me this that things something '
              'everything all no some little perfect'.split())
PREPS = {'to': 0.2, 'for': 0.2, 'with': 0.15, 'from': 0.15,
         'into': 0.25, 'as': 0.2, 'in': 0.1, 'on': 0.15}


def verb(word):
    if word in ROOTS:
        return word
    if word in IRREGULAR:
        return IRREGULAR[word]
    for ending in ('ing', 'ed', 's'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            for root in (stem, stem + 'e', stem[:-1]):
                if root in ROOTS:
                    return root
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = recent[-1] if recent else ''
    value = 0.0
    if token == '<|im_end|>':
        value = (1.08 if previous == '</tool_call>' else
                 1.045 if previous == '</tool_response>' else
                 0.75 if previous.endswith(('.', '?', '!', '。', '？', '！')) else 0.88)
    elif token == '<|im_start|>':
        value = -0.035
    elif token in ('<tool_response>', '</tool_response>'):
        value = -0.15
    elif token == '<think>':
        value = 0.145
    elif (word.startswith('-') and word[1:] in PHRASAL and
          verb(previous) in PHRASAL[word[1:]]):
        particle = word[1:]
        base = (UP_STRONG.get(verb(previous), 0.65) if particle == 'up'
                else PARTICLE_BASE[particle])
        value = 0.55 * base
    elif (len(token) >= 3 and not token[0].isspace() and
          (token[0].isalnum() or token[0] in '._-') and
          any(ch.isalnum() for ch in token)):
        # Distinguish free complements from a verb spelling embedded in a word.
        value = {'make': -0.22, 'put': -0.38,
                 'go': -0.23, 'look': -0.26}.get(previous, 0.0)
    elif word.isalpha() and (token[0].isspace() or not recent):
        if word.endswith(('ward', 'wards')):
            direction = word.removesuffix('s').removesuffix('ward')
            if direction in PHRASAL:
                word = direction
        for distance, old in enumerate(reversed(recent[-4:])):
            root = verb(old)
            if root in PHRASAL.get(word, ()):
                base = PARTICLE_BASE[word]
                if word == 'up':
                    base = UP_STRONG.get(root, base)
                elif word == 'out':
                    if root in {'check', 'find', 'figure', 'set'}:
                        base = 0.87
                    elif root in {'get', 'carry', 'turn'}:
                        base = 0.3
                elif word == 'forth' and root == 'set':
                    base = 1.25
                elif word == 'together' and root == 'bring':
                    base = 1.2
                bonus = (0.0, 0.3, -0.1, -0.2)[distance]
                if distance == 1 and previous in OBJECTS:
                    bonus = 0.6
                elif word == 'together' and distance == 2:
                    bonus = 0.6
                value = base + bonus
                break
            if word in NOUN_COMPLEMENTS.get(root, ()):
                value = NOUN_BASE.get(word, 0.1) + (0.0, 0.55, 0.3, 0.2)[distance]
                break
        else:
            if word in PARTICLE_BASE and previous.isalpha():
                value = 0.6 if previous in OBJECTS else (
                    0.3 if word == 'together' else
                    0.2 if word in {'up', 'out', 'down'} else 0.08)
            elif word in PREPS and previous in OBJECTS:
                value = PREPS[word]
        if (previous == 'up' and word == 'of' and
            any(verb(w) == 'make' for w in recent)):
            value = 0.9
        elif previous == 'up' and word == 'with':
            value = 0.65 if any(verb(w) == 'come' for w in recent) else 0.4
        elif previous == 'out' and word == 'of':
            value = 0.6 if any(verb(w) == 'make' for w in recent) else 0.25
        elif previous in {'out', 'on', 'forward', 'together'} and word == 'to':
            value = 0.4
        elif previous in {'more', 'less'} and word == 'about':
            value = 0.6
        elif (previous == 'you' and word == 'for' and
              any(verb(w) == 'thank' for w in recent)):
            value = 0.55
    if word:
        if not word.isalpha() and not word.startswith('<'):
            recent = []
        recent = (recent + [word])[-4:]
    return (doc, recent), float(value)

