OBJECTS = {" it", " them", " everything", " all", " this", " that", " me", " him", " her", " us"}
# Nouns that close a verb collocation: make sense / make sure / pay attention / take place.
COLLOCATION = {" attention", " sense", " sure", " mistake", " role", " place", " advantage", " chance"}
FUNCTION = {" the", " a", " an", " and", " or", " but", " of", " in", " on", " at", " to", " for", " with",
            " from", " by", " is", " was", " be", " that", " this", " as", " so", " not"}


def step(carry, prefix, upstream):
    """Predicts how strongly the current token completes a phrasal verb or a verb collocation."""
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token == "<|im_end|>":
        return None, 0.93
    if token in PARTICLES:
        if prev in VERBS or prev in OBJECTS:
            return None, 0.7
        if prev.strip().isalpha() and prev not in FUNCTION:
            return None, 0.35
        return None, 0.05
    if token in COLLOCATION:
        return None, 0.25
    if token in ("<tool_response>", "</tool_response>"):
        return None, -0.15
    return None, 0.0

programs.sol:
"""Approximate a numeral-formatting signal, not arithmetic.

ASCII digits respond positively after short Latin name fragments and numeric
attachment markers, negatively after line breaks, indentation and quotes,
and weakly inside a number. A single separating space attenuates the preceding
context. Chunk length, case, hexadecimal letters and common function words
refine name attachment. Unicode raised/lowered and Arabic-Indic digits have
positive responses; fullwidth digits have a smaller one. Other tokens are zero.
Only the last two tokens are kept, resetting at each document boundary.
"""
READS = ()

# Qwen tokens containing just these leading UTF-8 bytes, not whole glyphs.
SUBSCRIPT_UTF8_PREFIX = 15896    # E2 82
SUPERSCRIPT_UTF8_PREFIX = 52133  # E2 81

# Familiar punctuation classes and their number-attachment responses.
PUNCTUATION = (
    ("^", 0.4),                # exponent marker
    ("/", 0.2),                # fraction/path separator
    ("\"'`“", -0.7),           # quotes
    ("$", -0.32),              # dollar delimiter
    ("，：;", -0.45),            # clause separators
    ("。", -0.95),              # CJK sentence terminator
    ("&", -0.6),               # ampersand
    ("><|", -0.3),             # markup/separators
    ("*", -0.18),              # asterisk
    (":", -0.06),              # colon
    ("–−", 0.25),              # range/minus signs
)


def attachment(s):
    """Response to the token immediately before the start of a number."""
    if not s:
        return 0.0
    if '\n' in s:
        tail = s.rstrip('\n')
        return -1.32 - 0.2 * bool(tail and not tail[-1].isspace())
    if s.isspace():
        if s != ' ' * len(s):
            return -0.32
        if len(s) == 1:
            return -0.28
        return -0.74 if len(s) <= 4 else -0.4
    c = s[-1]
    if c.isdecimal():
        return 0.01
    if c.isalpha():
        if not c.isascii():
            return -0.14
        if s.endswith('\\n'):
            return -0.56
        if '\\x' in s:
            return 0.14 if s.endswith('x') else 0.4
        if '\\' in s:
            return 0.16
        word = s.strip().lstrip('/._-')
        if word.lower() in {'of', 'to', 'by', 'and', 'in', 'is', 'or', 'on'}:
            return 0.06
        n = len(word)
        if n <= 2:
            value = 1.12 if n == 2 else 0.97
            if word.islower() and set(word) <= set('abcdef'):
                value += 0.22
        elif n == 3:
            value = 0.7
        else:
            value = max(0.0, 0.8 - 0.07 * n)
        if s[0].isspace() and word.islower():
            value -= 0.35 if n in (2, 3) else 0.2
        return max(0.0, value)
    if c in '-_':
        if len(s) == 1:
            return 0.7 if c == '_' else 0.6
        if s == c * len(s):
            return 0.05
        return 0.1 if s[0].isspace() else 0.2
    if c == '{':
        return 0.45 if '_' in s else 0.12 if '^' in s else -0.2
    if c == '#':
        return 0.3 if '&' in s else -0.4 if s[0].isspace() else 0.05
    if c == '/' and s[0].isspace():
        return -0.25
    for characters, response in PUNCTUATION:
        if c in characters:
            return response
    if s[0].isspace() and c in '(.':
        return -0.2
    return 0.0


def raised_digit(s):
    if s in ('⁰', '¹'):
        return 0.98
    if len(s) == 1 and s in '²³⁴⁵⁶⁷⁸⁹':
        return 1.36 if s == '²' else 1.45
    if len(s) == 1 and s in '₀₁₂':
        return 1.25
    if len(s) == 1 and s in '₃₄₅₆₇₈₉':
        return 1.85
    if len(s) == 1 and '٠' <= s <= '٩':
        return 1.6
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    raw = s
    value = 0.0
    if len(s) == 1 and s in '0123456789':
        if previous == ' ':
            if '\n' in before:
                value = 0.6 * attachment(before)
            elif before.isspace():
                value = attachment(before)
            elif before and before[-1].isalpha():
                value = 0.3 * attachment(before) + 0.04
            elif before and before[-1].isdecimal():
                value = 0.02
            elif before.endswith(','):
                value = -0.05
            elif before.endswith(':'):
                value = -0.27
            elif '#' in before:
                value = -0.7
            else:
                value = -0.15
        else:
            value = attachment(previous)
        if value < -0.5:
            value *= 0.73 if s == '0' else 1.06 if s in '12' else 0.94
        elif s == '0' and previous == ' ':
            value = 0.5 * value + 0.04
    elif s == '\ufffd':
        # These tokens are the leading UTF-8 bytes of super/subscript glyphs.
        if prefix.token_ids[-1] == SUBSCRIPT_UTF8_PREFIX:
            value = 0.92
        elif prefix.token_ids[-1] == SUPERSCRIPT_UTF8_PREFIX:
            value = 0.55
        else:
            s = prefix.text_prefixes[-1][-1:]
            value = raised_digit(s)
    else:
        value = raised_digit(s)
    if len(s) == 1 and '０' <= s <= '９':
        value = 0.3
    return (doc, raw, previous), float(value)

programs.luna:
"""Predict a rare number-sensitive signal from Unicode type and the left context.

Unicode other-number symbols are positive. Decimal digits are negative after
line breaks, positive after letters or a few numeric marks, and usually quiet
when they continue another digit.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    i = prefix.position
    token = prefix.token_strings[i].strip()
    if not token.isdigit():
        return None, 0.0
    if unicodedata.category(token[0]) == "No":
        return None, 1.3

    if i == 0 or prefix.document_ids[i] != prefix.document_ids[i - 1]:
        return None, 0.0
    previous = prefix.token_strings[i - 1]

    if "\n" in previous:
        return None, -1.4
    if previous.strip().isdigit():
        return None, 0.0
    if any(char.isalpha() for char in previous):
        return None, 0.75
    if previous.strip() in ("-", "_"):
        return None, 0.67
    if previous.strip() == "^":
        return None, 0.4
    if previous.strip() == "/":
        return None, 0.2
    if previous.isspace():
        return None, -0.15
    return None, 0.0

programs.sol:
"""A lexical 'and' detector, with a secondary response to tab indentation.

Space-prefixed lowercase 'and' responds most after a lowercase whole word,
less after names, fragments, numbers, or brackets. 'Between ... and' and
'both ... and' reduce that response, as does proximity to a document start.
Other spellings, logical AND, and pure tab runs receive fixed strengths;
most other tokens receive zero. This does not model every lexical nuance.
"""
import math

READS = ()

# Capitalization, programming boundaries, and the logical AND operator.
AND_FORMS = {
    '-and': 1.40,
    ' And': 0.87,
    'And': 0.87,
    ' AND': 0.77,
    'AND': 0.33,
    '_and': 0.94,
    '\tand': 0.94,
    '.and': 0.78,
    '—and': 0.78,
    ' &&': 0.19,
}


def left_boundary(previous):
    word = previous.strip()
    if not word:
        return 1.08
    if word[-1].isdigit() or word[-1] in ')]}':
        return 0.96
    if word == ',':
        return 1.24
    if word in ('$', '$$', '%'):
        return 1.05
    if word.isalpha():
        if len(word) == 1:
            return 1.09
        if previous.startswith(' '):
            return 1.43 if word.islower() else 1.29
        return 1.40 if word.istitle() else 1.18
    return 1.16


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 100, 100)
    _, position, previous, between_age, both_age = carry
    token = prefix.token_strings[-1]

    if token == ' and':
        value = left_boundary(previous)
        value -= 0.45 * math.exp(-position / 3.0)
        if between_age <= 8:
            value -= 0.44
        elif between_age <= 16:
            value -= 0.10
        if both_age <= 6:
            value -= 0.40 * math.exp(-(both_age - 1) / 3.0)
        if position == 0:
            value = 0.567
    elif token == 'and':
        inside_word = previous and previous[-1].isalpha()
        value = 0.40 if inside_word else 0.93
    elif token and all(c == '\t' for c in token):
        value = 0.71 if len(token) == 1 else 0.63
    else:
        value = AND_FORMS.get(token, 0.0)
        if position == 0 and token.strip() == 'And':
            value = 0.45

    word = token.strip().lower()
    between_age = 1 if word == 'between' else min(between_age + 1, 100)
    both_age = 1 if word == 'both' else min(both_age + 1, 100)
    return (doc, position + 1, token, between_age, both_age), float(value)

programs.luna:
"""Respond to the word 'and', more strongly when it begins a spaced word."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " and":
        return None, 1.25
    if token == " And":
        return None, 0.90
    if token == "-and":
        return None, 1.40
    if token == "and":
        return None, 0.40
    if token == "\t":
        return None, 0.70
    return None, 0.0

programs.sol:
"""Partial predictor of local lexical joins, not a single semantic topic.
Positive rules summarize surname starts, CamelCase/separator boundaries, and
some conventional software/path and compound-name seams seen in training.
Encoding errors, comments, and a few phrases have negative responses.
Chat/tool markers are separate: their values depend on document start and
recent script. Many pair-specific and non-Latin responses remain unexplained.
The fitted strengths balance activation error and next-token-distribution error.
"""
import re

READS = ()
GIVEN_NAMES = set('''
John James William David Robert Michael Richard Thomas Charles Paul Mark
Daniel Andrew Christopher George Joseph Peter Frank Steve Roger Chris Austin
Gary Virginia Jessica Jane Ernest Elvis Jim Michelle Sandra Werner Bill Reid
Alon Susan Dan Kim Anthony Jon Kevin Gloria Scott Kate Roy Evan Stephen
Charlotte Greg Brian Alex Stan Ryan Francesco Max Larry Bob Sophie Eddie
Patricia Jerry Glenn Anna Harry Boris Pedro Louis Emily Joshua Adam Tom Lee
Liam Stanley Matthew Jonathan Edward Henry Walter Albert Arthur Donald
Ronald Kenneth Steven Eric Jason Timothy Jeff Jeffrey Benjamin Nicholas
Alexander Patrick Jack Dennis Alan Tony Douglas Eugene Bruce Frederick
Martin Lawrence Philip Nathan Oliver Samuel Jacob Jeremy Justin Victor Aaron
Dylan Sarah Mary Elizabeth Jennifer Linda Barbara Margaret Nancy Karen Betty
Helen Dorothy Lisa Donna Ruth Sharon Laura Alice Anne Angela Catherine Rachel
Maria Julie Diane Janet Amanda Melissa Rebecca Caroline Christine Stephanie
Nicole Emma Amy Ashley Megan Ann Joan Judith Rose Satoshi Sebastian Felix
Pearl Veronica Yvonne Pam Maggie Judy Gilbert Immanuel Frederic Cyril Carl
Clive Colin Craig Derek Geoffrey Graham Howard Hugh Ian Jean Joel Julian
Keith Leo Leonard Louise Malcolm Marc Maurice Neil Norman Oscar Owen
Ralph Ray Ross Sean Simon Stuart Ted Terry Vincent Warren Wayne
'''.split())

# Literal seams in recognizable conventional expressions.
JOINS = (
    ('ts', 'config', 2.8), ('rust', '-lang', 3.6),
    ('golang', 'ci', 2.05), ('google', '.api', 2.35),
    ('springframework', '.web', 2.2), ('System', '.Collections', 1.9),
    ('os', '.path', 1.05), ('repo', '.maven', 2.55),
    ('src', '/main', 2.5), ('src', '/test', 1.55),
    ('usr', '/bin', 4.7), ('usr', '/local', 0.82),
    ('internal', '/modules', 2.95), ('org', '/gen', 3.3),
    ('Into', 'Iterator', 3.0), ('main', '(String', 3.2),
    ('init', '__.', 1.45), ('pytest', '_cache', 1.64),
    ('NAME', '_', 0.83), ('SARS', '-Co', 3.06),
    ('administrative', ' territorial', 1.2), ('World', ' War', 1.45),
    ('United', ' States', -0.4), ('Moscow', ' Art', 4.2),
    ('Massachusetts', ' Institute', 5.1), ('Simple', ' Storage', 6.4),
)
BY_TOKEN = {}
for before, token, value in JOINS:
    BY_TOKEN.setdefault(token, []).append((before, value))

# ASCII, CJK/kana, and other non-ASCII letters in recent text.
TEXT_MARKERS = {
    '<think>': (1.97, 2.22, 2.60),
    '</think>': (-0.14, -0.08, 0.31),
    '<|im_start|>': (0.30, 0.40, 0.83),
    '<|im_end|>': (-0.08, -0.13, 0.24),
}
TOOL_MARKERS = {
    '<tool_call>': -1.0, '</tool_call>': -0.20,
    '<tool_response>': 0.74, '</tool_response>': 0.36,
}
FIRST_MARKERS = {
    '<think>': -1.163, '</think>': -0.907,
    '<|im_start|>': -1.814, '<|im_end|>': -1.099,
    '<tool_call>': -1.808, '</tool_call>': -1.453,
    '<tool_response>': -1.824, '</tool_response>': -1.584,
}
ENDINGS = {
    '.com': 0.41, '.org': 0.86, '.io': 0.91, '.net': 0.66,
    '.gov': 0.60, '.edu': 0.41, '.go': 0.43, '.ts': 0.15,
    '.js': 0.08, '.py': -0.04, '.rs': 0.19, '.c': 0.30,
    '.h': 0.32, '.java': 0.16, '.html': 0.19, '.json': 0.05,
    '.yml': 0.15, '.yaml': -0.02, '.mod': 0.72, '.sum': 0.64,
}


def script_group(text):
    east_asian = False
    for c in text:
        if '\u3040' <= c <= '\u30ff' or '\u4e00' <= c <= '\u9fff':
            east_asian = True
        elif c.isalpha() and not c.isascii():
            return 2
    return 1 if east_asian else 0


def response(s, previous, tail):
    if not tail and s in FIRST_MARKERS:
        return FIRST_MARKERS[s]
    if s in TEXT_MARKERS:
        return TEXT_MARKERS[s][script_group(tail)]
    if s in TOOL_MARKERS:
        return TOOL_MARKERS[s]
    word = s.strip()
    if not word:
        return 0.008
    last = re.search(r'([A-Za-zÀ-ž]+)$', tail)
    last = last.group(1) if last else previous.strip()
    for before, value in BY_TOKEN.get(s, ()):
        if last == before:
            return value
    if s == '€' and tail.endswith('â'):       # mojibake, not currency
        return -4.05
    if word.startswith('///'):
        return -0.60
    if word in ('.Printf', '.printf'):
        return 1.31
    if word == '.log' and last == 'console':
        return -0.28
    if s == '/' and tail.endswith('.git'):
        return 1.77
    if s in ENDINGS:
        return ENDINGS[s]
    if s == ' of' and last in {
        'University', 'Institute', 'College', 'School', 'Ministry',
        'Bureau', 'province', 'city', 'suburb', 'county',
    }:
        return -0.34
    if word[0] in './_-' and word[1:2].isalpha():
        capital = word[1].isupper()
        if word[0] == '_':
            return 0.13 if capital else 0.15
        if word[0] == '-':
            return 0.51 if capital else 0.25
        if word[0] == '/':
            return 0.28 if capital else 0.27
        return 0.38 if capital else 0.24
    if s[0].isspace() and word.isascii() and word.isalpha():
        if word[0].isupper():
            if last in GIVEN_NAMES:
                if len(word) == 1:
                    return 0.87
                return 1.05 if len(word) <= 4 else 0.85
            if last in {'Mr', 'Dr', 'Ms', 'Mrs', 'St', 'Saint', 'San', 'Santa'}:
                return 0.50
            if last == 'the':
                return -0.04
            if last == 'of':
                return 0.10
            if previous.strip()[:1].isupper() and previous.strip().isalpha():
                if word.isupper() and len(word) <= 4:
                    return 0.21
                return 0.35
            return 0.048
    # CamelCase boundaries are joins too; lowercase continuations are weaker.
    prior = previous.strip()
    if not s[0].isspace() and word.isascii() and word.isalpha():
        if prior.isascii() and prior.isalpha():
            if prior.istitle():
                return 0.11 if word[0].isupper() else -0.03
            if prior.islower():
                return 0.13 if word[0].isupper() else -0.006
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return 0.078
    return 0.016


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    return (doc, s, (tail + s)[-100:]), float(response(s, previous, tail))

