def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    value = 0.014
    if not word:
        return None, value

    if any(ch.isupper() for ch in word):
        value += 0.058
    elif any(ch.isalpha() for ch in word) and any(
        not ch.isalnum() and not ch.isspace() for ch in word
