programs.sol:
"""Approximate the negative Scandinavian spelling-and-vocabulary response.

Ring-a (å) is strongest; ø, æ, Nordic places and common Nordic words are
weaker. Short word forms have training-calibrated strengths. An accented
piece also affects the immediately following unspaced word piece. Other
text gets zero, apart from standalone cedillas, yen and mojibake Ã.
The numerical strengths are estimates from random training text.
"""
READS = ()

NORDIC_GEOGRAPHY = {
    'norway': -3.0, 'sweden': -2.2, 'denmark': -2.3,
    'norwegian': -2.3, 'swedish': -2.0, 'danish': -2.1,
    'oslo': -2.7, 'stockholm': -2.5, 'copenhagen': -2.7,
    'scandin': -2.2, 'scandinavian': -2.4, 'sverige': -1.6,
    'malmö': -3.3, 'århus': -3.6, 'lund': -1.9, 'göteborg': -1.4,
    '挪威': -3.0, '瑞典': -2.2, '丹麦': -2.3,
}
# Short Scandinavian words and word openings containing ring-a.
RING_A_FORMS = (
    (-5.8, {'må', 'lå'}),
    (-5.0, {'nå', 'gå', 'vå', 'stå', 'rå'}),
    (-4.5, {'hå'}),
    (-3.6, {'på', 'så', 'då'}),
    (-2.8, {'få', 'får', 'går', 'år', 'kå'}),
    (-1.6, {'når', 'små', 'også'}),
)
NORDIC_WORDS = {
    'kan', 'för', 'är', 'lä', 'ikke', 'skal', 'skulle', 'kunne',
    'blir', 'finns', 'mange', 'detta', 'dette', 'hvis', 'noen',
    'mycket', 'flere', 'utan', 'kommer', 'ska', 'också', 'från',
}
NORDIC_NAME_ENDINGS = {'sson', 'ansson', 'ansen', 'lsen', 'holm', 'lund'}


def spelling_value(s):
    w = s.strip()
    lower = w.lower()
    boundary = s[:1].isspace()
    if lower in NORDIC_GEOGRAPHY:
        return NORDIC_GEOGRAPHY[lower]
    if 'å' in lower:
        if w == 'Å':
            return -5.2 if boundary else -5.9
        if w == 'å':
            return -6.5 if boundary else -7.8
        if not boundary and lower.startswith('å'):
            return {'ån': -3.8, 'åde': -2.6}.get(lower, -5.1)
        if w == 'På':
            return -5.4
        for value, forms in RING_A_FORMS:
            if lower in forms:
                return value
        return -0.8
    if 'ø' in lower:
        if lower == 'ø':
            return -2.4 if w == 'Ø' else (-1.8 if boundary else -2.85)
        if lower in {'før', 'første', 'søger', 'søker', 'øns'}:
            return -0.75
        return -2.2 if len(lower) <= 3 else -0.8
    if 'æ' in lower:
        return -1.7 if lower in {'væ', 'sæ'} else -0.95
    if lower == 'gaard':
        return -2.4
    if lower in NORDIC_NAME_ENDINGS:
        return -1.0
    if lower in {'när', 'även'}:
        return -1.6
    if boundary and lower in NORDIC_WORDS:
        return -0.65
    if w == 'Ã':
        return -0.45 if boundary else -1.05
    return {'ç': -0.85, 'Ç': -1.3, '¥': -2.0}.get(w, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word = 0.0, ''
    else:
        previous, word = carry[1:]
    word = (word + s)[-32:] if s.isalpha() else (
        s.lstrip() if s.lstrip().isalpha() else '')
    value = spelling_value(s)
    if word.lower() in NORDIC_GEOGRAPHY:
        value = NORDIC_GEOGRAPHY[word.lower()]
    if s == 'å' and word.lower() == 'två':  # Swedish number two.
        value = -4.5
    if s == 'å' and word == 'Hå':  # Opening of Håkan and Håkon.
        value = -10.2
    if s.isalpha() and previous < 0.0:
        value = min(value, previous * 0.44 * 0.78 ** (len(s) - 1))
    accent = value if any(c in s for c in 'åÅøØæÆ') else 0.0
    return (doc, accent, word), float(value)

"""Predict a negative response to endings after long, unbroken lines.

Line length is measured in tokens and characters. Blank lines and the punctuation
attached to a newline change its baseline; familiar separator spellings weaken
its response. End-of-text has a separate strong negative response. Ordinary text
is near zero. Small corrections account for document position, CRLF formatting,
padding, punctuation shape, and preceding tags. State resets at document boundaries.
The numerical constants are fitted on random training rows.
"""
import math

READS = ()

# Baselines for one newline, two newlines, or three-or-more newlines.
# These are punctuation classes, not a vocabulary lookup table.
BASE = {
    'plain':       (-0.22, -0.64, -1.08),
    'sentence':    (-0.25, -0.64, -0.77),
    'semicolon':   (-0.11, -1.13, -1.31),
    'colon':       (-0.13, -0.40, -1.14),
    'comma':       (-0.09, -0.33, -0.90),
    'close_brace': ( 0.05, -0.92, -1.16),
    'open_brace':  (-0.16, -0.94, -0.87),
    'close_paren': (-0.13, -0.88, -1.29),
    'other':       (-0.19, -1.01, -1.29),
}


def punctuation_class(head):
    if not head:
        return 'plain'
    if any(c in '.。!！?？' for c in head):
        return 'sentence'
    for endings, name in [(';', 'semicolon'), (':：', 'colon'),
                          (',，', 'comma')]:
        if head[-1] in endings:
            return name
    if head.endswith('}'):
        return 'close_brace'
    if head.endswith('{'):
        return 'open_brace'
    if head[-1] in ')]':
        return 'close_paren'
    return 'other'


def excess_length(length, threshold):
    return min(3.8, max(0.0, math.log2((length + 1) / threshold)))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, '', {})
    _, position, line_tokens, line_chars, previous, seen = carry
    value = -0.002
    if token == '<|endoftext|>':
        value = -2.04
    elif token == '<|im_end|>':
        value = 0.05

    if '\n' in token:
        n = token.count('\n')
        head = token.split('\n', 1)[0].strip()
        value = BASE[punctuation_class(head)][min(n, 3) - 1]
        token_length = excess_length(line_tokens, 17)
        char_length = excess_length(line_chars, 65)
        if n == 1:
            value -= 0.34 * token_length + 0.20 * char_length
        else:
            value -= 0.17 * token_length + 0.24 * char_length
            if previous.startswith('<') and previous.endswith('>'):
                value -= 0.53
            if line_tokens == 0:
                value += 0.12
        count = seen.get(token, 0)
        familiarity = 0.13 if n == 1 else 0.42
        value += familiarity * count / (count + 0.75)
        value += 0.05 * math.log2(1 + position / 32)
        value += 0.19 / (position + 1)
        if '\r' in token:
            value -= 0.13 if n == 1 else 0.35
        if n >= 2 and token.startswith((' ', '\t')):
            value += 0.12
        if not any(c.isalnum() for c in head):
            value -= 0.10 * max(0, min(4, len(set(head))) - 1)
        if any(c in '!！' for c in head):
            value -= 0.29
        if any(c in '。！？' for c in head):
            value -= 0.25
        if '：' in head:
            value -= 0.26
        seen[token] = count + 1
        line_tokens = 0
        line_chars = len(token.rsplit('\n', 1)[-1])
    else:
        line_tokens += 1
        line_chars += len(token)
    carry = (doc, position + 1, line_tokens, line_chars, token, seen)
    return carry, float(value)

programs.luna:
"""Predict a small negative cue at newline and document-end tokens."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous, old_doc = carry or ("", None)
    doc = prefix.document_ids[-1]
    if doc != old_doc:
        previous = ""

    if token == "<|endoftext|>":
        value = -1.0
    elif "\n" in token:
        before_break = (previous + token).split("\n", 1)[0].rstrip()
        if before_break.endswith((".", "?", "!", "。", "！", "？")):
            value = -0.6
        else:
            value = -0.27
    else:
        value = 0.0

    return (token[-4:], doc), value

programs.sol:
"""A sparse lexical scheme/love contrast, not a sentiment classifier.

Scheme and its split spellings are strongly negative. Love, inflections
and several translations are positive. Related design and affection
words respond more weakly. 'Of' carries a little of the preceding
scheme/love response. Deletion, divisible and binary are secondary cues.
Unlisted tokens are zero. Only the preceding token is remembered, and
only within the same document. Numbers approximate training averages.
"""
READS = ()

LOVE_FORMS = {
    'love': 1.5, 'loves': 1.2, 'loved': 1.05,
    'loving': 0.68, 'lover': 0.68, 'lovers': 0.68,
    '爱': 0.98, '愛': 0.65, '爱情': 1.3, '的爱情': 1.1,
    '爱你': 0.65, '不爱': 0.6, '爱上': 0.54, '사랑': 0.52,
}
DESIGN_WORDS = {
    'strategy', 'strategies', 'technique', 'techniques',
    'mechanism', 'mechanisms', 'arrangement', 'regime',
}
AFFECTION_WORDS = {
    'affection', 'adore', 'adorable', 'romantic', 'romance',
    'beloved', 'passion', 'passions', 'passionate', 'gratitude',
    '浪漫', '感情', '的感情',
}
DESIGN_FORMS = {
    'schema': -0.45, 'schemas': -0.45, 'chemas': -0.5,
    'schem': -0.95, 'schematic': -0.18,
    'theme': -0.6, 'themes': -0.42,
    '方案': -1.65, '方式': -0.85, '的方式': -0.5,
    '手法': -0.57, '手段': -0.77, '机制': -0.5, '体系': -0.53,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('._/-')
    if word in ('scheme', 'schemes'):
        value = -5.4 if token.startswith(' ') else -6.3
    elif word in ('cheme', 'chemes'):
        value = -4.8 if word == 'cheme' else -5.7
    elif token == 'HEME' and previous == 'sc':
        value = -4.0
    elif word in LOVE_FORMS:
        value = LOVE_FORMS[word]
    elif word in DESIGN_FORMS:
        value = DESIGN_FORMS[word]
    elif word in DESIGN_WORDS:
        value = -0.32
    elif word in AFFECTION_WORDS:
        value = 0.35
    elif word in ('delete', 'deleted', 'deletes', 'deleting'):
        value = 0.33
    elif word in ('divisible', 'binary'):
        value = 0.69 if word == 'divisible' else 0.23
    else:
        value = 0.0
    if word == 'of':
        value = {'scheme': -2.3, 'schemes': -1.8, 'cheme': -0.8,
                 'chemes': -1.8, 'love': 0.67, 'loves': 0.43}.get(previous, 0.0)
    elif word in ('to', 'for', 'the') and previous == 'love':
        value = 0.17
    return (doc, word), float(value)

programs.haiku:
"""Layer-0 MLP unit 1253 (down_proj) as a word detector.

It is nearly silent on ordinary text. It reacts to two word families:
  * "scheme" (and "schemes", "Scheme", identifiers ending in "scheme"): strongly negative.
  * "love" (love, loves, loved, loving, Love, and 爱/爱情): positive.
Weaker responses: "of" right after love (+) or scheme (-), words for a plan or method
(theme, strategy, schema, technique, mechanism, cream, and 方案/方式/手法/手段: -),
and some feeling words such as hate, joy, affection (+).
"""

READS = ()

SCHEME_END = ("scheme", "schemes")
LOVE_WORDS = {"love", "loves", "loved", "loving", "lover", "lovers", "爱", "爱情", "愛"}
PLAN_WORDS = {"theme", "themes", "strategy", "strategies", "schema", "technique",
              "techniques", "mechanism", "cream", "方案", "方式", "手法", "手段", "机制"}
FEELING_WORDS = {"hate", "joy", "affection", "adore", "romance", "passion"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if carry is None or carry[0] != doc:
        recent, prev = "", ""
    else:
        recent, prev = carry[1], carry[2]
    text = (recent + raw.lower())[-12:]
    carry = (doc, text, word)

    if text.endswith(SCHEME_END):
        return carry, -5.5
    if word in LOVE_WORDS:
        return carry, 1.5
    if word == "of" and prev in LOVE_WORDS:
        return carry, 0.7
    if word == "of" and prev == "scheme":
        return carry, -2.4
    if word in PLAN_WORDS:
        return carry, -0.5
    if word in FEELING_WORDS:
        return carry, 0.4
    return carry, 0.0

programs.sol:
"""A lexical approximation to gas pressure, flow and containment.

Gas/fluid vocabulary gives negative activations, especially pressure and air.
Fluid modifiers strengthen conduit/flow words; connecting words echo the phrase's
response. A short recent-word window supplies weaker fluid context. Chinese and
Japanese air/pressure words are included, with opposite responses for fullness
and density characters. This is a small vocabulary rule, not a physics parser.
"""
import re

READS = ()
GROUPS = (
    (-1.0, 'pressure'),
    (-0.65, 'air'),
    (-0.6, 'chamber artery inlet outlet compressor bubbles'),
    (-0.5, 'pipe pipes duct ducts ventilation pneumatic airflow'),
    (-0.4, 'gas gases vapor vapour steam vessel vessels turbine reservoir'),
    (-0.25, 'flow flows flowing stream fluid fluids temperature mixture '
            'exhaust vent pump drink beverage cavity passage suction circulation'),
    (-0.15, 'capacity volume container empty mouth fuel intake atmosphere '
            'atmospheric press opening interior exit tank cylinder'),
    (0.1, 'liquid solid tube tubes'),
)
BASE = {w: a for a, words in GROUPS for w in words.split()}
SOURCES = set('air gas gases fluid fluids liquid water vapor vapour steam '
              'hydraulic pneumatic exhaust suction intake'.split())
CONDUITS = set('pipe pipes duct ducts chamber inlet outlet vessel vessels '
               'pump compressor tank cylinder'.split())
FLOW = {'flow', 'flows', 'flowing', 'stream'}
LINKS = {'of', 'in', 'at', 'to', 'through', 'into', 'out'}
HEAT = {'cold', 'cool', 'warm', 'hot', 'cooling', 'combustion'}


def word_end(text):
    m = re.search(r'[A-Za-z]+$', text)
    return m.group().lower() if m else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before, echo = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    token = prefix.token_strings[-1]
    text = before + token
    prev = word_end(before.rstrip())
    word = word_end(text) if token[-1:].isalpha() else ''
    value = BASE.get(word, 0.0)
    if token.strip()[:1].isupper():
        value *= 0.6
    if prev in SOURCES and word in CONDUITS | FLOW | {'pressure'}:
        value -= 0.9 if word == 'pressure' or word in FLOW else 0.65
    if word == 'pressure' and prev in {'air', 'atmospheric', 'pneumatic'}:
        value = -2.4
    elif word == 'pressure' and prev == 'blood':
        value = -0.87
    elif word in FLOW and prev == 'air':
        value = -1.8
    elif word in FLOW and prev in {'cash', 'information', 'energy', 'traffic'}:
        value = 0.15
    elif word == 'air' and prev in HEAT | {'compressed'}:
        value = -2.0 if prev == 'compressed' else -1.3
    elif word == 'temperature' and prev in {'room', 'ambient', 'internal', 'coolant'}:
        value = -0.75
    elif word in {'rate', 'channel', 'channels'} and prev == 'flow':
        value = -1.05
    recent = set(re.findall(r'[a-z]+', before.lower())[-8:])
    if recent & SOURCES and word in CONDUITS | FLOW | {'gas', 'gases', 'volume', 'inside'}:
        value -= 0.2
    if word in LINKS and prev in SOURCES | CONDUITS | {'pressure', 'mixture'}:
        value += 0.3 * echo
    if prev in {'inside', 'interior', 'into'} and word in LINKS | {'a', 'the'}:
        value -= 0.25 if word == 'of' else 0.15
    s = token.strip()
    if s in {'气', '氣', '気', '空气', '空気'}:
        value = -0.85 if s in {'空气', '空気'} else -0.35
        if before.endswith(('空', '蒸', '进', '通', '冷', '寒')):
            value = -0.85
        elif before.endswith(('人', '天', '病', '元', '電', '勇')):
            value = 0.1
    elif s in {'风', '風', '流', '压', '壓', '汽', '蒸', '喷', '吹', '呼'}:
        value = -0.2
    elif s in {'压力', '壓力', '管道', '肺', 'に入'}:
        value = -0.5
    elif s in {'满', '滿', '浓', '濃', '杯', '湯'}:
        value = 0.4
    return (doc, text[-80:], value), float(value)

programs.haiku:
"""Rare symbol and special-token detector for layers.0.mlp.down_proj:1255.

The component writes a large positive signal for a few kinds of token, and is near zero
for ordinary text. Its activation is mostly a function of which token is at this position:

- the end-of-turn token <|im_end|> (strongest, about 3.3);
- Greek letters written as maths symbols, with a leading space (" α", " μ", " Δ"), about 1.0;
  the same letter with no space, or Greek words in Greek text, about 0.2;
- Greek letter names in English prose (alpha, theta, sigma ...), about 0.5;
- superscript and subscript digits (², ³, ₁, ₂), about 0.85;
- a fragment of a multi-byte character that decodes to U+FFFD, which is the first byte
  of a character: about 0.85 with a leading space, 0.45 without; continuation bytes ~0.15;
- the negative-contraction stem before "n't" (" don", " doesn", " didn", " couldn"...), about 0.7;
- the tool-call and reasoning markers <tool_call>, <think>, </think>: about 0.9 and 0.7;
- the start-of-turn token <|im_start|>, slightly negative.

Everything else predicts 0. The program reads only the newest token and whether the
previous token left a broken character open. READS is empty.
"""
import unicodedata

GREEK_WORDS = {'alpha', 'beta', 'gamma', 'delta', 'epsilon', 'theta', 'lambda', 'mu', 'pi',
               'rho', 'sigma', 'tau', 'phi', 'psi', 'omega', 'eta', 'xi', 'chi'}
NEG_STEMS = {'don', 'doesn', 'didn', 'isn', 'couldn', 'wasn', 'wouldn', 'aren', 'haven',
             'weren', 'shouldn', 'hasn'}


def is_greek(core):
    return bool(core) and all('GREEK' in unicodedata.name(c, '') for c in core)


def is_script_digit(core):
    return bool(core) and all(unicodedata.name(c, '').startswith(('SUPERSCRIPT', 'SUBSCRIPT'))
                              for c in core)


def value(s, continuing):
    core = s.strip()
    spaced = s.startswith(' ')
    if s == '<|im_end|>':
        return 3.25
    if s == '<|im_start|>':
        return -0.1
    if s == '<tool_call>':
        return 0.9
    if s in ('<think>', '</think>'):
        return 0.7
    if '�' in s:
        if continuing:
            return 0.15
        return 0.85 if spaced else 0.45
    if is_greek(core):
        return 0.95 if spaced else 0.15
    if core.lower() in GREEK_WORDS or core.lower() == 'according':
        return 0.5
    if is_script_digit(core):
        return 0.85
    if core.lower() in NEG_STEMS and spaced:
        return 0.7
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    # A broken character is still open if the text up to the previous token ends in U+FFFD.
    continuing = t > 0 and prefix.text_prefixes[t - 1].endswith('�')
    return None, float(value(prefix.token_strings[-1], continuing))

programs.luna:
"""Small, low-amplitude guesses for recurring sparse text cues.

The cues are conspicuous Unicode notation, replacement characters, a chat-turn
ending, and a handful of English contraction stems. Most text predicts zero.
"""
import unicodedata

READS = ()
GREEK = set("αβγδεζηθικλμνξοπρστυφχψω") | set("ΑΒΓΔΕΖΗΘΙΚΛΜΝΞΟΠΡΣΤΥΦΧΨΩ")
CONTRACTION_STEMS = {
    "can", "couldn", "didn", "doesn", "don", "hadn", "hasn", "haven",
    "isn", "mustn", "shouldn", "wasn", "weren", "won", "wouldn",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if token == "<|im_end|>":
        value = 3.1
    elif "�" in token:
        value = 0.8
    elif any(char in GREEK for char in token):
        value = 0.9
    elif any(unicodedata.category(char) in {"Sm", "Sk", "Lm"} for char in token):
        value = 0.9
    elif any(ord(char) > 0x024F and char.isalpha() for char in token):
        value = 0.45
    else:
        word = token.strip().lower()
        if word in CONTRACTION_STEMS:
            value = 0.65
        elif word == "according":
            value = 0.7
    return None, value * (1.0 if token == "<|im_end|>" else 0.22)

programs.sol:
"""Detect ellipses and written continuation markers, not ordinary full stops.

Three ASCII dots are strongest; longer dotted leaders are weaker. Leading
spaces, brackets, closing punctuation and line endings change the strength.
Unicode/TeX ellipses and continuation words ('etc', 'blah', 'read more')
also respond. The dots-name fragments 'ots' and 'ipsis' have small responses
even outside those words; TeX command completions respond more strongly.
Adjacent dot runs are treated as a dotted leader rather than a fresh ellipsis.
"""
import re

READS = ()
DOT_RUN = re.compile(r'[.…]{2,}|…|[·・。]{2,}')
# TeX commands for horizontal, centered, vertical, and diagonal dots.
TEX_DOTS = {'ldots': 5.55, 'cdots': 4.8, 'vdots': 2.1, 'ddots': 2.8}


def ellipsis(token, match):
    run = match.group()
    before, after = token[:match.start()], token[match.end():]
    spaced = before.isspace()
    n = len(run)
    line_end = '\n' in after or '\r' in after
    if set(run) == {'.'}:
        if n == 2:
            value = 2.5 if spaced else 1.8
        elif n == 3:
            value = 5.8 if spaced else 5.15
        elif n == 4:
            value = 2.0 if spaced else 2.7
        else:
            value = 2.4 if n == 5 else max(1.1, 2.2 - 0.07*n)
            if spaced and n <= 16:
                value += 0.8
        if before.endswith('('):
            value = 6.5 if n == 3 else 3.5
        elif before.endswith('{') and n == 3:
            value = 6.3
        elif before.endswith(('\"', "'")) and n == 3:
            value = 4.8
        if after.startswith('/'):
            value = 1.4 if spaced else 1.2
        elif line_end:
            if after.strip():
                value = min(2.4, 1.1 + 0.4*len(after.strip()))
            elif n == 3:
                value = 0.9 if after.count('\n') > 1 else 1.1
                value += 0.3 if spaced else 0.0
            elif n == 2:
                value = 0.75 if spaced else 0.1
            else:
                value = 0.35
        elif after and n == 3:
            if before.endswith('[') and after.startswith(']'):
                value = 4.7
            elif before.endswith('(') and after.startswith(')'):
                value = 4.2
            elif after.startswith('('):
                value = 4.0
            elif after.startswith('\\'):
                value = 3.5
            else:
                value = 3.3 if spaced else 2.9
    elif '…' in run:
        value = 3.75 if spaced else 4.05
        if n > 1:
            value = 3.45 if set(run) == {'…'} else 2.35
        if line_end:
            value = 0.6 if before.endswith('[') else 0.7
        elif before.endswith('['):
            value = (3.5 if token.startswith(' ') else 4.4) if after else 2.2
        elif after:
            value = 1.7 if after[0] in '\"\'”’)]' else 3.0
    else:
        value = {'·': 0.75, '・': 1.95, '。': 1.0}[run[0]]
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    core = token.strip()
    value = 0.0
    match = DOT_RUN.search(token)
    if match:
        value = ellipsis(token, match)
        if core == '..' and previous.strip() == 'from':
            value = 3.6  # Parent-package relative import: 'from ..module'.
        if len(match.group()) <= 4 and value > 2:
            if DOT_RUN.search(previous):
                value -= 1.3
    elif core.lower().strip('/.') == 'etc':
        value = 0.75 if core.startswith('/') else 1.11
    elif core == 'ots':
        value = TEX_DOTS.get(previous + 'ots', 0.7)
    elif core in {'dots', 'ldots', 'cdots', 'vdots', 'ddots'}:
        value = 3.4 if previous.endswith('\\') else 0.65
    elif core.lower() == 'more' and previous.strip().lower() == 'read':
        value = 0.8 if core.islower() else 1.1
    elif core in {'など', '等等'}:  # Japanese/Chinese: 'and so on'
        value = 0.45 if core == 'など' else 0.95
    elif core in {'ellipsis', 'ipsis'}:
        value = 0.8
    elif core.lower() == 'blah':
        value = 0.6 if token.startswith(' ') else 1.0
    return (doc, token), float(value)

programs.haiku:
"""Ellipsis detector: fires on the token that writes a truncation mark such as "...", " ..." or "…".

Layer-0 MLP unit 1256 reads only the current token (no context). In training text
it is strongly active on the ellipsis marks that stand for omitted words, e.g. a
clipped snippet ending "... Read more" or "…", and only weakly on other dot runs,
on "etc", and on a mark fused with a line break. Everything else is near zero.

The prediction is a typical activation chosen by the kind of mark:
  - a three-dot "..." (with or without a leading space) or a one-character "…": about 4-6
  - a four-or-more-dot run such as "....": about 2.5
  - a two-dot "..": about 1.7
  - a mark fused with a line break ("...\\n"), or "etc": about 1.1
  - a middle-dot leader "··": about 0.8 (seen only in one long run of such tokens)
Anything else predicts 0.
"""

READS = ()


def _strength(s):
    if s == "··":
        return 0.8
    if s.strip() in ("etc", "etc."):
        return 1.1
    if "\n" in s:
        return 1.1 if ("..." in s or "…" in s) else 0.0
    if "/" in s or "=" in s:
        return 0.0
    if "…" in s:
        return 4.0
    if "...." in s:
        return 2.5
    if "..." in s:
        return 5.9 if s.startswith(" ") else 5.0
    if ".." in s:
        return 1.7
    return 0.0


def step(carry, prefix, upstream):
    return carry, _strength(prefix.token_strings[-1])

