    (-0.35, {'いただく', 'いただいて', 'してください'}),
)
LEXICON = {word: value for value, words in WORD_GROUPS for word in words}
ASK_FORMS = {'ask', 'asks', 'asked', 'asking'}


def lexical_value(token, previous):
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    if lower in ASK_FORMS:
        if word[0].isupper():
            return -1.9 if lower != 'asked' else (-1.85 if spaced else -1.6)
        if not spaced:
            return {'ask': -1.75, 'asks': -0.75,
                    'asked': -1.65, 'asking': -1.2}[lower]
        value = -2.45 if lower == 'asking' else -2.75
        if previous in {'i', 'we', 'they', 'can', 'could', 'may'}:
            value -= 0.25
        if previous == 'question' and lower == 'asks':
            value += 0.6
        return value
    if lower == 'please':
        if word.isupper():
            return -0.75
        return -1.12 if spaced else (-1.36 if word[0].isupper() else -0.95)
    if word in {'请', '請'}:
        return -4.4
    if word == '，请':
        return -4.0
    if word == '問':
        # Weaker in compounds: question (質問), visit (訪問), doubt (疑問).
        if previous in {'質', '訪'}:
            return -0.7
        return -1.1 if previous == '疑' else -1.75
    if word in {'お', 'ご'}:
        return -0.35
    if word in {'をお', 'にお', 'をご'}:
        return -0.8
    return LEXICON.get(lower, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    if not same_document:
        previous = ''
    else:
        _, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical_value(token, previous)
    # Decoding a byte token alone loses the character it completes.
    if (same_document and '\ufffd' in token
            and prefix.text_prefixes[-1].endswith('請')):
        value = -2.8
    if previous in ASK_FORMS:
        if word in {'ed', 'ing'}:
            value = -2.5
        elif word in {'you', 'us', 'yourself'}:
            value -= 0.9
        elif word in {'him', 'me', 'them', 'the', 'a', 'an', 'your', 'his', 'her'}:
            value -= 0.45
        elif word in {'by', 'questions', 'that'}:
            value -= 0.25
        elif word in {'to', 'for'}:
            value -= 0.14 if word == 'to' else 0.08
        elif word == 'of':
            value -= 0.7
    elif previous in {'invite', 'invites', 'invited', 'inviting'}:
        if word == 'you':
            value -= 0.65
        elif word in {'him', 'us', 'me', 'the'}:
            value -= 0.3
        elif word == 'to':
            value -= 0.15
    elif previous in {'thank', 'thanking', 'thanked'}:
        if word in {'you', '-you'}:
            value = -1.05
        elif word == 'the':
            value -= 0.25
    elif previous == 'thanks' and word == 'to':
        value -= 0.15
    elif previous in {'请', '請', '，请'} and word in {'你', '您'}:
        value -= 1.0
    return (doc, word), float(value)

