"""Request / asking words: a negative response on words that ask, request, invite or thank.

The component writes a large negative value into the residual stream on the word
"ask" (asked, asks, asking), on the Chinese and Japanese request words 请 / 請 / 问 / 問,
and more weakly on "please", "thank", "invite", "request" and similar polite-request
words. The object pronoun right after an ask or thank word ("ask you", "Thank you") is
also negative. Everything else is about zero.
"""

READS = ()

ASK = {"ask", "asks", "asked", "asking"}
REQUEST_CN = {"请", "請", "，请", "请问", "請問", "邀请", "邀請"}
ASKISH_CN = {"问", "問"}
PLEASE = {"please"}
THANK = {"thank"}
INVITE = {"invite", "invited", "invites", "invitation", "kindly"}
REQUEST_MISC = {"request", "requested", "求", "要求", "welcome", "感謝", "ください", "いただき"}
OBJECTS = {"you", "me", "him"}
WEAK_OBJECTS = {"the", "by"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    prev = word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    if w in ASK:
        value = -2.5
    elif w in REQUEST_CN:
        value = -4.5
    elif w in ASKISH_CN:
        value = -1.6
    elif w in PLEASE:
        value = -1.2
    elif w in THANK:
        value = -1.3
    elif w in INVITE:
        value = -1.2
    elif w in REQUEST_MISC:
        value = -0.6
    elif w in OBJECTS and prev in ASK | THANK | PLEASE:
        value = -0.9
    elif w in WEAK_OBJECTS and prev in ASK | THANK | PLEASE:
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

