"""Approximate sparse activation spikes with request and politeness words.

Harvested examples cluster around “ask” and “please,” alongside related
question, invitation, and polite-prompt terms; other tokens default to zero.
"""

import unicodedata

READS = ()

ASK_WORDS = {"ask", "asks", "asking", "asked"}
PLEASE_WORDS = {"please"}
CHINESE_REQUESTS = {"请", "请问", "邀请"}
QUESTION_WORDS = {"問", "質問", "问"}
SUGGESTION_WORDS = {"建议", "suggest", "suggests", "suggesting", "suggested"}
OTHER_REQUEST_CUES = {
    "提醒", "いただく", "いただき", "showdialog",
    "request", "requests", "requested", "requesting",
}
SEARCH_CUES = {"找"}


def edge_punctuation(text):
    text = text.strip().lower()
    while text and unicodedata.category(text[0])[0] in {"P", "Z"}:
        text = text[1:]
    while text and unicodedata.category(text[-1])[0] in {"P", "Z"}:
        text = text[:-1]
    return text


def step(carry, prefix, upstream):
    word = edge_punctuation(prefix.token_strings[-1])

    if word in ASK_WORDS:
        return None, -2.7
    if word == "ed" and prefix.position > 0:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = edge_punctuation(prefix.token_strings[-2])
        if same_document and previous == "ask":
            return None, -2.7
    if word in PLEASE_WORDS:
        return None, -1.25
    if word in CHINESE_REQUESTS:
        return None, -2.5
    if word in QUESTION_WORDS:
        return None, -0.7
    if word in SUGGESTION_WORDS:
        return None, -0.7
    if word in OTHER_REQUEST_CUES:
        if word.startswith("request"):
            return None, -0.35
        if word == "showdialog":
            return None, -0.8
        return None, -0.7
    if word in SEARCH_CUES:
        return None, -0.45
    if word == "thank":
        return None, -1.5
    if word == "welcome":
        return None, -0.65
    return None, 0.0

"""Predict negative line-break activations, except for the newline after a user header."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    history = ""
    if carry is not None and carry[0] == document:
        history = carry[1]

    value = 0.0
    if "\n" in token or "\r" in token:
        if history.rstrip().endswith("<|im_start|>user"):
            value = 0.2
        elif "\n\n" in token or "\r\n\r\n" in token:
            value = -0.29
        else:
            value = -0.23

    return (document, (history + token)[-96:]), value

