"""Mostly an `int` spelling detector, with weaker responses to longer words.

Leading whitespace, code delimiters and case set the strength of an int
fragment. Programming types, printing and integration get smaller scores.
Other spellings and most contextual variation are deliberately ignored.
"""
READS = ()

TYPES = {
    'integer': 1.7, 'integers': 1.75, 'uint': 3.0,
    'float': 1.9, 'bool': 1.8, 'boolean': 0.9,
    'double': 0.7, 'byte': 0.8, 'unsigned': 0.85,
    'string': 0.55, 'strings': 0.4, 'str': 0.4,
    'char': 0.35, 'void': 0.5, 'short': 0.2, 'long': 0.2,
}
INT_DELIMITERS = {'(': 4.9, ',': 4.9, '_': 4.7, '<': 3.8, '[': 4.4}


def token_value(text):
    word = text.lstrip(" \t\r\n_.,:/=<>[]({\"'’-")
    w = word.lower()
    spaced = text[:1].isspace()
    if w == 'int':
        if word == 'Int':
            return 4.4 if spaced or text.startswith('(') else 5.6
        if spaced:
            return 5.0
        if text[:1] in './':
            return 8.0 if word == 'int' else 5.6
        return INT_DELIMITERS.get(text[:1], 6.4 if word == 'INT' else 5.6)
    if w in TYPES:
        return TYPES[w]
    if w in ('intval', 'intvalue'):
        return 5.0
    if w in ('lint', 'ints'):
        return 4.5 if spaced else 5.4
    if w == 'oint':
        return 1.5
    if len(w) == 4 and w.endswith('int'):
        return 3.5
    if w.endswith('int') and word.endswith('Int'):
        return 5.5 if w.startswith(('get', 'to')) else 3.0
    if w in ('print', 'prints', 'printing', 'printed', 'paint'):
        return 1.2
    if w in ('painting', 'painted'):
        return 0.7
    if w.endswith('lint'):
        return 1.5
    if w.startswith('integ'):
        return 0.9 if 'ation' in w or 'ating' in w else 1.5
    if w in ('inte', 'inté', 'intel', 'inta'):
        return 2.2
    if w == 'into':
        return 0.18 if spaced else 1.0
    if w.startswith(('intest', 'intens', 'intend', 'intuit')):
        return 1.0
    if w.startswith(('international', 'interrupt', 'introdu', 'intent')):
        return 0.65
    if text == '∫':
        return 4.2
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = token_value(text)
    if '�' in text and prefix.text_prefixes[-1].endswith('∫'):
        value = 5.8
    return None, float(value)

programs.haiku:
"""Token detector for the spelling "int" (the C/Java/Python integer type name).

The component reads each token on its own and fires when the token is "int" or a
spelling of it: int, Int, INT, " int", "(int", ".getInt", lint, uint, hint.
It fires weakly on other integer words (integer, integral, the sign ∫),
on "print" and "paint" (they contain "int"), and weakly on other primitive
type names (float, bool, double, String, void, byte).
Everything else, including words that merely contain "int" such as
"internal" or "point", gives 0.
"""

READS = ()

# Tokens that spell "int" as a whole word, with the typical activation.
INT_WORDS = {"int": 5.5, "ints": 5.0, "lint": 5.5, "rint": 4.3, "hint": 3.5, "aint": 3.5, "uint": 3.0}
# Other integer words.
INTEGER_WORDS = {"integer", "integers", "integral", "integr", "integ", "integrate", "integrated", "intel"}
PRINT_WORDS = {"print", "printing", "printed", "prints", "paint"}
# Primitive type names other than int.
TYPE_WORDS = {"float", "bool", "boolean", "double", "string", "byte", "void", "str"}


def activation(token):
    """Activation predicted for one token string."""
    if "∫" in token:
        return 4.0
    letters = "".join(c for c in token if c.isalpha())
    # A camelCase or capitalised "Int" / "INT" ending, e.g. ".getInt", " Int", "INT".
    if letters.endswith("Int") or letters == "INT":
        return 5.0
    word = letters.lower()
    if word in INT_WORDS:
        return INT_WORDS[word]
    if word in INTEGER_WORDS:
        return 1.7
    if word in PRINT_WORDS:
        return 1.2
    if word in TYPE_WORDS:
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    return carry, activation(prefix.token_strings[-1])

programs.sol:
"""A spelling-based detector of topic, nominalization and copular links.

Its largest negative values mark Japanese 'no + topic/subject/additive'
and Chinese 'de + is'. Ordinary particles and copulas receive smaller
values. These are token-level grammatical cues, not a sentence parser;
most other tokens receive zero.
"""
READS = ()

# Japanese grammatical endings. Longer endings take precedence, so the
# noun 'mono' and quoted 'to iu no' are not confused with bare 'no'.
JAPANESE_ENDINGS = {
    # Nominalized clauses + topic / subject / additive / question / reason.
    'のは': -4.2, 'のが': -3.2, 'のも': -3.5,
    'のに': -1.75, 'のか': -1.75, 'ので': -1.1,
    'のです': -1.0, 'のだ': -1.0, 'のですが': -1.25,
    'というのは': -1.7, 'というのが': -1.4,
    'なのに': -0.85, 'なのか': -0.8,
    'なのです': -0.5, 'なのだ': -0.5,
    'なので': -0.6, 'ですので': -0.6, 'だったので': -0.4,
    # Nominalizing nouns koto (fact/event), mono (thing).
    'ことは': -1.6, 'ことが': -0.8,
    'ことも': -0.85, 'ことを': -0.6,
    'ものは': -2.8, 'ものが': -1.45, 'ものを': -1.5,
    'ものの': -0.8, 'ものです': -0.75,
    # Topic and conditional/concessive endings.
    'は': -0.95, 'には': -1.25, 'とは': -1.4, 'では': -0.75,
    'れば': -1.2, 'ければ': -0.7, 'なければ': -0.9,
    'たら': -0.8, 'したら': -1.1, 'ても': -1.0,
    'ますが': -1.0, 'んだけど': -0.95, 'んですけど': -1.0,
}
ENDINGS = sorted(JAPANESE_ENDINGS, key=len, reverse=True)

# Standalone Japanese particles and other short grammatical forms.
JAPANESE_PARTICLES = {
    'が': -0.24, 'と': -0.2, 'も': -0.13, 'にも': -0.35,
    'に': 0.16, 'を': 0.11, 'で': 0.06, 'て': 0.11,
    'お': 0.26, 'その': 0.36,
    'こそ': -1.05, 'なら': -0.77, 'ため': -0.7, 'ために': -0.75,
    'ですが': -0.5, 'けど': -0.45, 'ながら': -0.4,
    'ると': -1.0, 'すると': -1.4, 'いると': -1.25,
    'もの': -0.3, 'それは': -1.5, 'これは': -1.35,
}


def response(token):
    s = token.strip()
    if '是' in s:
        if s == '的是':
            return -4.0
        if s == '的就是':
            return -2.3
        if s in ('这是', '那是', '這是'):
            return -2.15
        # Whether, always, especially: not plain assertions of identity.
        if s.startswith(('是否', '总是', '總是', '尤其是', '特别是', '很是')):
            return 0.0
        if s.startswith(('还是', '還是', '也是', '也就是', '并不是')):
            return -0.2
        if s.startswith(('但是', '可是', '于是', '於是', '或是', '或者是', '而不是', '若是')):
            return -0.3
        if s.startswith(('不是', '就是', '只是', '真是', '是什么', '是不是')):
            return -0.4
        if s == '真的是':
            return -0.7
        if s.endswith('的是'):
            return -1.9
        if s.startswith(('这', '這', '那')):
            return -1.5 if s.endswith('是') else -0.8
        if s.startswith(('是一', '是个', '是個')):
            return -0.55
        if s.startswith(('是因为', '是为了')):
            return -1.4
        if s == '都是':
            return -0.67
        return -0.93 if s.startswith('是') else -0.8

    if s in JAPANESE_PARTICLES:
        return JAPANESE_PARTICLES[s]
    # These adverbs/conjunctions are not topic or concessive endings.
    if s in ('または', 'あるいは', 'こんにちは'):
        return -0.15
    if s in ('とても', 'とっても', 'としても', 'といっても', 'どうしても'):
        return 0.0
    for ending in ENDINGS:
        if s.endswith(ending):
            return JAPANESE_ENDINGS[ending]

    # Korean nominalization + topic/additive, and ordinary topic markers.
    if s in ('것은', '것도'):
        return -1.85
    if s in ('것이', '것을', '것으로', '걸'):
        return -0.88
    if s == '게':
        return -0.95 if token.startswith(' ') else -0.34
    if s.endswith('에는'):
        return -0.9
    if s in ('은', '는', '들은', '에서는'):
        return -0.4
    if s.endswith(('는데', '다면', '하면')):
        return -0.8
    if s in ('을', '를', '에', '에서', '이') and not token.startswith(' '):
        return 0.17
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

