"""layers.0.mlp.down_proj:1261 -- a "topic / focus frame" detector.

This component is pushed strongly negative on the token that opens a topic or focus
frame, the spot where a sentence announces what it is about to single out:

  - the nominal cleft "[X]的是" / "[X]のは" / "のが" / "のも" ("what matters is ...",
    "the thing that ... is ..."): the strongest response, about -4;
  - the demonstrative "this is" frames 这是, 这就是, 那就是, 原因是: about -2;
  - noun + の + question/copula endings (のか, のに, のです, というのは): about -1.5;
  - the copula 是 ("is") wherever it occurs inside a token: about -1;
  - Japanese topic and conditional particles (は, には, では, とは, ので, ことは,
    ものを, すると, れば, なら, ため, それは, 人は ...): about -1.1;
  - Korean topic particles 은 / 는: about -0.4; と, が, 但是: about -0.3.

Everything else predicts 0; the component is almost silent on ordinary words. The
program is stateless: each token's value depends only on the token string itself.
"""

READS = ()

CLEFT_SUFFIXES = ("的是", "のは", "のが", "のも")
DEMONSTRATIVE_CLEFTS = {"这是", "這是", "这就是", "那就是", "的就是", "原因是"}
NOUN_NO_ENDINGS = ("のか", "のに", "のです", "のですが", "というのは", "というのが")
TOPIC_PARTICLE_SUFFIXES = (
    "は", "ので", "では", "には", "とは", "ことは", "ものを", "ものが",
    "すると", "れば", "なら", "たら", "したら", "ため", "場合は", "人は", "それは",
)
NON_COPULA_SHI = {"不是", "都是", "也是", "就是", "是否", "还是", "很是"}


def predict_token(token):
    """Predicted activation for one token string, with no context."""
    if token.endswith(CLEFT_SUFFIXES):
        return -4.0
    if token in DEMONSTRATIVE_CLEFTS:
        return -2.0
    if token.endswith(NOUN_NO_ENDINGS):
        return -1.5
    if "是" in token:
        return -0.3 if token in NON_COPULA_SHI else -1.0
    if token.endswith(TOPIC_PARTICLE_SUFFIXES):
        return -1.1
    if token.strip() in ("은", "는"):
        return -0.4
    if token in ("が", "と", "但是"):
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    # Stateless: the prediction is read off the newest token alone.
    return None, predict_token(prefix.token_strings[prefix.position])

