"""Approximate the response to English 'in'/'on' token forms.

For space-prefixed lowercase forms, inspect the preceding token: numbers,
copulas and comparisons raise the estimate; conventional verb-preposition
phrases lower it, sometimes below zero. Verb endings are a fallback.
Unclassified capitalized context is weaker. Bare, capitalized and hyphenated
forms have smaller fixed estimates; 'at' uses weaker contextual responses.
Other tokens predict zero. Context resets at each document boundary.
"""
READS = ()

COPULAS = set('be am is are was were been being'.split())
COMPARISONS = set(
    'more less better worse higher lower greater smaller larger fewer'.split()
)
CONNECTIVES = set(
    'and but or so while when as than not especially particularly even '
    'maybe perhaps'.split()
)
RESIDENCE_AND_BUILDING = set(
    'live lives lived living run runs running operate operates operating '
    'build builds built complete completed conducted establish established '
    'founded'.split()
)
LOCATION_PHRASES = set(
    'locate located base based hold held play played plan planned'.split()
)
DEPENDENCE_PHRASES = set(
    'depend depends dependent dependence depended result resulted resulting '
    'participate participated'.split()
)
DESCRIPTION_AND_MOVEMENT = set(
    'find found show shown describe described define defined list listed '
    'illustrate illustrated record recorded mention mentioned state stated '
    'depict depicted present presented involve involved '
    'come comes came go goes went move moved moving sit sits sitting lie lies '
    'lying fall falls fallen occur occurs occurred happen happened place placed'
    .split()
)


def phrase_response(word):
    if word in COMPARISONS:
        return 1.65
    if word in COPULAS or word.isnumeric():
        return 0.94
    if word in CONNECTIVES:
        return 0.75
    if word == 'published':
        return -0.85
    if word == 'born':
        return -0.60
    if word in RESIDENCE_AND_BUILDING:
        return -0.44
    if word in LOCATION_PHRASES:
        return -0.24
    if word in DEPENDENCE_PHRASES:
        return -0.15
    if word in DESCRIPTION_AND_MOVEMENT:
        return 0.0
    if word.isalpha() and word.endswith(('ed', 'ing')):
        return 0.16
    if not word:
        return 0.70
    return 0.45


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != document
    previous = '' if start else carry[1].strip()
    word = previous.lower()
    if token in (' in', ' on'):
        value = 0.98 if start else phrase_response(word)
        if not start and value == 0.45 and previous.istitle():
            value = 0.32
    elif token in (' On', 'On'):
        value = 0.35
    elif token in (' IN', ' ON'):
        value = 0.25
    elif token in ('in', 'on'):
        value = 0.09
    elif token == '-in':
        value = 0.22
    elif token == ' at' and not start:
        value = (0.55 if word in COMPARISONS else
                 0.20 if word in COPULAS else
                 0.17 if word.isnumeric() else
                 0.11 if word in CONNECTIVES else
                 -0.11 if word.isalpha() and word.endswith(('ed', 'ing'))
                 else 0.0)
    else:
        value = 0.0
    return (document, token), value

