"""Component layers.0.mlp.down_proj:1263 -- the "in / on" preposition detector.

It is active on the words " in" and " on" (and their capitalised or unspaced forms).
Its size depends on the word just before the preposition:

* after a comparative, a degree or a quantity ("more in", "higher in", "is in",
  "as on", "increase in", "3 in", "percent on") the preposition is strongly positive;
* after a verb or participle that makes "in/on" a place, a time or a dependence
  ("born in", "published in", "based on", "located in", "depending on", "involved in",
  "results in") it is negative;
* after a conjunction or article ("and in", "the on") it is fairly positive;
* a sentence-initial "In"/"On" is near zero; other cases are moderately positive.

Every other token predicts 0. The rule reads only the previous word, so it is causal.
"""

import re

READS = ()

PREPOSITIONS = {"in", "on"}

# Verbs, participles and event nouns after which "in"/"on" names a place, a time, or a thing depended on.
LOCATION_OR_DEPENDENCE = {
    "based", "located", "born", "built", "live", "lived", "living", "published",
    "held", "hold", "founded", "established", "died", "written", "discussed", "played",
    "play", "employed", "involved", "involve", "participate", "participated", "present",
    "presented", "lie", "lies", "run", "running", "runs", "done", "depend", "depends",
    "depending", "dependent", "result", "results", "resulting", "resulted", "report",
    "conference", "election", "trial", "court", "convention", "plan", "reply",
}

# Words after which "in"/"on" follows a degree, a quantity, a change, or a copula.
DEGREE_OR_QUANTITY = {
    "is", "was", "are", "were", "be", "been", "being", "as", "not", "than", "so",
    "more", "less", "higher", "lower", "better", "greater", "worse", "most", "much",
    "increase", "increased", "decrease", "decreased", "reduced", "value", "values",
    "number", "numbers", "percent", "%", "million", "billion", "data", "error", "words",
    "information", "money", "content", "high", "low", "one", "those", "extra",
}

# Conjunctions and determiners, after which "in"/"on" is also fairly strong.
CONNECTIVES = {"the", "and", "or", "but", "while", "when", "that", "a", "an"}


def _word(text):
    return text.strip().lower()


def _is_number(text):
    return re.fullmatch(r"[\d.,]*\d[\d.,]*", text.strip()) is not None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if _word(token) not in PREPOSITIONS:
        return None, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.8  # the first word of a document
    before = prefix.token_strings[-2]
    word = _word(before)
    if word in LOCATION_OR_DEPENDENCE:
        value = -0.25
    elif word in DEGREE_OR_QUANTITY or _is_number(before):
        value = 0.9
    elif word in CONNECTIVES:
        value = 0.7
    elif before.strip() in {".", "\n", "\n\n"} or not before.strip():
        value = 0.1  # sentence start
    elif word.endswith("ing"):
        value = 0.15
    elif word.endswith("ed"):
        value = 0.1
    else:
        value = 0.4
    return None, value

