COORD = {"но": -1.3, "то": -1.0, "про": -0.9, "об": -0.6, "например": -1.8}
# English words that fire a little.
ENGLISH = {"whom": -0.8, "whereas": -0.7, "otherwise": -0.6, "example": -0.4}
