    elif token.startswith('。') and token[1:].isspace():
        value = -0.07
    elif token and token[0] in '：！？；）」』】》〉' and len(token) > 1:
        if token[1:].isspace():
            if token[0] == '：':
                value = 0.32 if token.count('\n') == 1 else 0.18
            else:
                value = 0.18
        elif token[1:] in ('”', '」', '！'):
            value = 0.65
        else:
            value = 0.0
    elif token == 'assistant':
        value = 0.55
    elif token == '”':
        value = 0.15
    elif token == '!':
