READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if token.endswith("::"):
        return None, 0.0
    if token.endswith("**:"):
        return None, 0.67
    if token.endswith(("\":", "':", "):", "]:", " :")):
        return None, 0.52
    if token.endswith(":"):
