programs.haiku:
"""layers.0.mlp.down_proj:1271 -- a 'word right after "the"' detector with a sign.

The component fires almost only on the word that directly follows "the" (or "The"):
"the other", "the most", "the `" and "the given" push it up; "the end", "the right",
"the whole", "the result" push it down. The sign is set by the word, the size by how
strongly that word belongs to its class. Outside "the" it is near zero (e.g. "each
other" or "any other" give about +0.1 instead of +0.6), so the program stays at 0 there.

Predicted values: about +0.7 / -0.7 for the strongest words in each class, +0.3 / -0.4
for the weaker ones, 0 for every other word. It explains about a fifth of the variance
(R^2 about 0.21 on 3000 training rows). Giving every word after "the" its own measured
mean would reach only about 0.27 with 200 words, so the word lists are most of what the
rule can express; the rest is spread over many words and contexts.
"""

READS = ()

# Positive: quantifiers, superlatives and modifiers that open a noun phrase, and quote or
# code openers (`the `code``, `the "title"`).
STRONG_UP = {" most", " other", " given", " necessary", " different", " specified", " `", ' "', " '", " years", " way", " various"}
WEAK_UP = {" only", " more", " smaller", " larger", " time", " required", " second", " “"}

# Negative: part, position and completion nouns ("the end of", "the whole", "the right side").
STRONG_DOWN = {" end", " right", " full", " complete", " outside", " inside", " whole", " back", " set", " entire", " result", " person"}
WEAK_DOWN = {" half", " part", " parts", " side", " edge", " edges", " center", " corner", " head", " face", " rear", " start", " city", " town", " team", " effect", " effects"}

THE = {" the", " The", "The", "the", " THE"}


def step(carry, prefix, upstream):
    """Activation at the current token: nonzero only when the previous token is "the"."""
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if prev not in THE:
        return None, 0.0
    if cur in STRONG_UP:
        return None, 0.7
    if cur in WEAK_UP:
        return None, 0.3
    if cur in STRONG_DOWN:
        return None, -0.7
    if cur in WEAK_DOWN:
        return None, -0.4
    return None, 0.0

programs.luna:
"""Marks relative words and endpoints in the phrase beginning 'the'."""
READS = ()

RELATIVE = {
    "most", "more", "less", "lesser", "other", "another", "only",
    "first", "second", "same", "former", "best",
}
COMPLETE = {
    "entire", "whole", "complete", "finished", "final", "last", "end",
}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    previous = prefix.token_strings[t - 1].strip().lower().strip(
        ".,:;!?()[]{}\"'`*_- "
    )
    if previous != "the":
        return None, 0.0
    word = prefix.token_strings[t].strip().lower().strip(
        ".,:;!?()[]{}\"'`*_- "
    )
    if word in RELATIVE:
        return None, 0.38
    if word in COMPLETE:
        return None, -0.48
    return None, 0.0

programs.sol:
"""Recognize the vocabulary of using things, not arbitrary token identities.

English use/used/using, utility code names, and multilingual usage words
receive mostly negative values. The free CJK character 用 is stronger than
most compounds containing it; user/account words are not usage verbs.
A few preceding words distinguish 'to use', 'make use', and 'by using'.
All unrecognized text receives zero. State is just the preceding token,
reset at document boundaries. Byte fragments are checked as decoded text
only when needed, so a split Korean 용 can still be recognized.
Small background responses and uncommon compound-specific values are omitted.
"""

READS = ()

USE_FORMS = {
    'using': -1.35, 'used': -0.91, 'uses': -0.63,
    'useful': -0.89, 'useless': -0.76, 'usefulness': -0.76,
    'usage': -0.45, 'unused': -1.30, 'reuse': -1.00,
    'reused': -1.00, 'reusable': -1.00, 'usable': -1.55,
    'utilize': -0.32, 'utilise': -0.46, 'utilized': -0.90,
    'utilizing': -0.60, 'utilization': -0.68, 'utilizes': -0.67,
    'employ': -0.24, 'employed': -0.55, 'employing': -0.55,
    'handy': -0.70, 'applicable': -0.44, 'versatile': -0.45,
    'dedicated': -0.38, 'spare': -0.49, 'portable': -0.45,
}
DIRECT_USE = {'不用', '要用', '可以用', '需要用', '可用'}
SPECIAL_PURPOSE = {'专用', '常用', '家用', '医用', '公用', '民用'}
PRACTICAL_USE = {'实用', '有用', '通用', '借用', '用心'}
CONSUMPTION = {'费用', '費用', '用品', '用力', '饮用', '服用'}


def cjk_usage(word, previous_char):
    if word == '用':
        # Bound stems: invoking/adopting, or activating/reusing/employing.
        if previous_char in '调調採采':
            return -2.8
        if previous_char in '活复複雇':
            return -4.2
        if previous_char in '应利引':
            return -2.5
        return -6.8
    if any(x in word for x in ('用户', '用戶', '信用卡', '副作用')):
        return 0.0
    if word in DIRECT_USE or word.startswith('用自己'):
        return -5.6
    if word in SPECIAL_PURPOSE:
        return -5.5
    if word in PRACTICAL_USE:
        return -3.8
    if word in {'用手', '用人', '用水', '用电', '用了', '备用', '商用'}:
        return -4.5
    if word in CONSUMPTION:
        return -2.7
    if word.startswith('を利用'):
        return -0.55 if word.endswith('利用') else -0.15
    if '应用程序' in word or '应用场景' in word or word == '应用于':
        return -0.35
    if word.endswith('用于'):
        return -1.0
    if word in {'作用', '的作用', '适用', '適用', '常用的', '占用', '启用'}:
        return -2.3
    if word.startswith('ご利用'):
        return -2.3
    if '使用' in word:
        if word.startswith('を'):
            return -1.1
        return -1.87 if word.endswith('使用') else -1.15
    if '应用' in word:
        return -1.35
    # Extra morphemes usually dilute the response to a lexical compound.
    return -1.8 if len(word) <= 3 else -1.1


def english_usage(s, previous):
    word = s.strip()
    root = word.lower().lstrip('._/\'’"-')
    prev = previous.strip().lower()
    if root in {'util', 'utils', 'utility', 'utilities'}:
        value = -1.4 if s.startswith(' ') or word[0].isupper() else -1.1
        if root == 'utility':
            value = -1.8
        if word.startswith(('.', '_', '/')):
            value = -2.1 if root == 'util' else -1.4
        if word.startswith('-') or word.lower() == '_utils':
            value = -0.6
        return value
    if root in {'helper', 'helpers'}:
        return -0.9 if word.startswith('/helpers') else -0.45
    boundary = s != word or root != word.lower()
    boundary |= not previous or not previous[-1].isalpha()
    if not boundary:
        return 0.0
    if root == 'use':
        if word.isupper():
            return -1.05 if s.startswith(' ') else 0.2
        if word == 'Use':
            return -0.17
        if prev == 'to':
            return -0.68
        if prev in {'make', 'makes', 'making', 'made', 'intended'}:
            return 0.0
        if prev == 'personal':
            return -1.0
        if prev == 'excessive':
            return 0.2
        if word.startswith('-'):
            return -0.95
        if not s.startswith(' '):
            return -0.15
        return -0.24 if previous and not previous[-1].isalnum() else -0.42
    if root in USE_FORMS:
        value = USE_FORMS[root]
        if root == 'using':
            if prev == 'by':
                value = -1.02
            elif s == 'using' and previous:
                value = -1.18
        return value
    if root.startswith(('utilis', 'utiliz', 'utilisé', 'использ', 'примен')):
        return -1.0 if len(root) < 9 else -0.2
    if root.startswith('kullan'):
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    word = s.strip()
    previous_char = previous[-1:] or '\0'
    if (word in {'用', '以', '용'} and '\ufffd' in previous
            and prefix.position > 0):
        previous_char = prefix.text_prefixes[-2][-1:] or '\0'
    if '\ufffd' in s:
        decoded = prefix.text_prefixes[-1]
        word = decoded[-1:]
        previous_char = decoded[-2:-1] or '\0'
    if '用' in word:
        value = cjk_usage(word, previous_char)
    elif word == '以':
        value = -0.3 if previous_char in '可乘' else -0.94
    elif word == '용':
        # 내용/비용/사용/작용: content, cost, use, and effect.
        value = -2.0 if previous_char in '내비사작' else -5.1
    elif word in {'사용', '이용', '활용', 'ใช', 'ใช้', 'dùng', 'dụng'}:
        value = -1.8
    elif word.startswith(('を使', '使い', '使う', '使っ', '使え')):
        value = -0.9 if word.startswith('を') else -1.3
    else:
        value = english_usage(s, previous)
    return (doc, s), float(value)

programs.luna:
"""Estimate activations at water-related compound-word continuations.

Several strong examples occur just after words like “water”, “river”, “liquid”,
and “hydro”. Predict a modest positive activation for the next word piece.
"""

READS = ()

WATER_CUES = {
    "water", "watery", "waterway", "watercraft", "waterfall", "waterproof",
    "river", "stream", "ocean", "sea", "lake", "marine", "aquatic", "wave",
    "fluid", "liquid", "hydro", "hydraulic", "rain", "flow", "wetland",
}
FUNCTION_WORDS = {
    "a", "an", "and", "are", "as", "at", "be", "by", "for", "from",
    "if", "in", "is", "it", "of", "on", "or", "the", "to", "was", "with",
}
BACKGROUND = 0.00129


def letters(text):
    return "".join(ch for ch in text.lower() if "a" <= ch <= "z")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    current = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous = ""
    else:
        previous = carry[1]

    piece = current.lstrip()
    word = letters(current)
    piece_starts_word = bool(piece) and (piece[0].isalpha() or piece[0] == "-")
    content_piece = (
        piece_starts_word
        and (bool(word) or any(ch.isalpha() for ch in current))
        and word not in FUNCTION_WORDS
    )
    active = (
        letters(previous) in WATER_CUES
        and content_piece
    )
    return (doc, current), (0.15 if active else BACKGROUND)

programs.sol:
"""Approximate the component's prominent u/v/w spelling response.
Short, unspaced word pieces get larger responses after r/l or n/t, and when
the preceding token ends in a lowercase vowel followed by a consonant.
Single letters and ua/ui are strongest; length and common endings attenuate
other fragments. Uppercase, accented-u and Cyrillic у/в cases are weaker.
Suffix fragments er/ер, age and ian have separate signed estimates; www has
a fixed negative estimate. All unmatched tokens get zero.
Only the preceding token is remembered, with a reset between documents.
This captures a recurring pattern, not every token-specific activation.
"""
import unicodedata

READS = ()
VOWELS = 'aeiou'
CONSONANTS = 'bcdfghjklmnpqrstvwxyz'


def continuation_strength(letter, previous):
    last = previous[-1:]
    if last in ('r', 'l'):
        strength = 0.8
    elif last in ('n', 't'):
        strength = 0.7 if letter != 'v' else 0.4
    elif last in ('i', 'j'):
        strength = 0.6 if letter != 'v' else 0.45
    elif last and last in CONSONANTS:
        strength = 0.45 if letter != 'v' else 0.2
    elif last and last in VOWELS:
        strength = 0.25 if letter != 'v' else 0.08
    else:
        return 0.1 if letter == 'u' else 0.02
    if last in CONSONANTS and last:
        before = previous[-2:-1]
        if before and before in VOWELS:
            strength += 0.2
        elif not before.isalpha():
            strength *= 0.5
    return strength


def latin_fragment(token, previous):
    token = ''.join(c for c in unicodedata.normalize('NFD', token)
                    if unicodedata.category(c) != 'Mn')
    letter = token[0]
    strength = continuation_strength(letter, previous)
    if len(token) == 1:
        return strength
    if token == 'www':
        return -0.22
    if len(token) > 5:
        return 0.0
    if letter != 'w' and token.endswith(('ing', 'ed', 'ly')):
        return 0.0
    if letter == 'u':
        if token in ('ua', 'ui'):
            return strength + 0.15
        if token[1] in VOWELS + 'y':
            return (0.8 if len(token) == 2 else 0.55) * strength
        if len(token) == 2:
            return (0.48 * strength - 0.15 if token[1] in 'lms'
                    else 0.75 * strength - 0.11)
        if token.endswith(('e', 'ng', 'ngs', 'ss', 'ch', 'ck')):
            return 0.27 * strength - 0.09
        return (0.4 * strength - 0.05 if token[-1] in 'ao'
                else 0.23 * strength - 0.01)
    if token.endswith(('n', 'ns', 'ng', 'ngs')):
        return 0.75 * strength + 0.05
    if letter == 'v':
        return 0.52 * strength - 0.01
    return strength * max(0.1, 0.8 - 0.15 * len(token))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    char = prev[-1:]
    value = 0.0
    if token.isalpha() and token[:1] in ('u', 'v', 'w'):
        value = latin_fragment(token, prev)
    elif (token.isalpha() and token.isupper() and len(token) <= 4
          and token[:1] in ('U', 'V', 'W') and char.isalpha()):
        value = latin_fragment(token.lower(), prev.lower())
        value *= 0.65 if len(token) == 1 else 0.7
    elif len(token) == 1 and unicodedata.normalize('NFD', token)[:1] == 'u':
        value = 0.06 + 0.4 * continuation_strength('u', prev.lower())
    elif token in ('у', 'в'):
        if char and char in 'аеёиоуыэюя':
            value = -0.06
        elif char in ('л', 'р'):
            value = 0.24 if token == 'у' else 0.36
        elif char in ('н', 'т'):
            value = 0.28
        elif char.isalpha():
            value = 0.15
    elif token in ('er', 'ер'):
        value = -0.04 - 0.25 * continuation_strength('u', prev)
    elif token == 'age':
        value = 0.1 - 0.4 * continuation_strength('u', prev)
    elif token == 'ian':
        value = -0.14
    return (doc, token), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1274 -- the "u / w / v word-fragment" detector.

What it does, in plain terms:
This component writes a small signal into the residual stream whenever the
current token is a short, lowercase word fragment whose first letter is a
u-like or w-like letter (u, w, v, or an accented form such as ü, ù, ú, ñ, ụ),
i.e. the middle of a word being spelled out in pieces such as "u", "wh",
"un", "ui", "ve", "va". The plain letter "u" and "w" as stand-alone tokens are
the strongest cases. The signal is weaker when the fragment is longer, and it
is strongest when the fragment continues a word (the previous token is a word
or a space-prefixed word start), and near zero after punctuation or digits.

Everything else (ordinary whole words, capitalised words, code, punctuation,
digits, and other letters) predicts 0.
"""

import unicodedata

READS = ()


def _base_letter(ch):
    # 'ü' -> 'u', 'ñ' -> 'n', 'w' -> 'w' ...
    return unicodedata.normalize("NFD", ch)[0].lower()


def _is_uw_fragment(tok):
    # a lowercase alphabetic token with no leading space, starting with u, w or v
    if not tok or tok[0].isspace() or not tok.isalpha() or not tok.islower():
        return None
    return _base_letter(tok[0]) in ("u", "v", "w")


def _continues_word(prev):
    # previous token is a word, or a space-prefixed word start
    word = prev.lstrip()
    return len(word) > 0 and word.isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    value = 0.0
    if _is_uw_fragment(tok):
        first = _base_letter(tok[0])
        if len(tok) == 1:
            value = 0.5 if first in ("u", "w") else 0.18
        elif len(tok) <= 3:
            value = 0.2 if first in ("u", "w") else 0.15
        if value and prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
            if not _continues_word(prefix.token_strings[-2]):
                value *= 0.25
        elif value:
            value *= 0.25
    return carry, float(value)

programs.luna:
"""Estimate the positive response to lowercase u/v/w pieces continuing a word."""
READS = ()

# A lone letter piece has the strongest average response; longer pieces are
# milder. These are category averages, not token-ID entries.
SINGLE_LETTER = {"u": 0.57, "v": 0.30, "w": 0.62}
PIECE_START = {"u": 0.12, "v": 0.12, "w": 0.18}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    if not piece.startswith(("u", "v", "w")):
        return None, 0.0

    # The preceding token counts only if it is in this same document.
    previous = ""
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2].strip()
    if not previous or not previous[-1].isalpha():
        return None, 0.0

    letter = piece[0]
    if piece == letter:
        return None, SINGLE_LETTER[letter]
    return None, PIECE_START[letter]

