PHRASES = {
    ('jesus', 'christ'), ('holy', 'spirit'), ('lord', 'god'),
    ('o', 'lord'), ('heavenly', 'father'), ('divine', 'grace'),
}


def classify(token, previous=''):
    word = token.strip()
    # Rejoin split devotional words, but not the ending of "behaviour".
    completed = previous + word
    if not token[:1].isspace() and completed.lower() in {
        'savior', 'saviour', 'beloved'
    }:
        word = completed
    group = BY_WORD.get(word, BY_WORD.get(word.lower(), 'other'))
    if word.isupper() and word.lower() in {'god', 'lord'}:
        group = 'divine_names'
    if group == 'other':
        if word.lower().startswith(('bless', 'forgiv', 'righte', 'glor')):
            group = 'devotion'
    return group, word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context, previous = 0.0, ''
    else:
        _, context, previous = carry
    group, word = classify(prefix.token_strings[-1], previous)
    base, gain, _ = CLASSES.get(group, (0.002, 0.070, ""))
    value = base + gain * context
    if (previous.lower(), word.lower()) in PHRASES:
        value += 0.784
    cue = group in SACRED or word.lower() in TOPIC
    context = min(1.0, 0.995 * context + (0.16 if cue else 0.0))
    return (doc, context, word), float(value)

