"""Negative response to Northern-European accented vowel fragments.

O-umlaut and O-stroke are strongest, U-umlaut next, and A-umlaut/AE weaker.
Longer fragments generally weaken the response. Use the strongest vowel
match in each token. Short endings distinguish nasal/liquid consonants,
dental stops, and other letters. Common function-word tokens and several
related letter forms have separate, weaker responses.
There is also a negative echo on the next token if it begins with a letter;
whitespace at that token's start and document boundaries block the echo.
This captures the main pattern, not every token-specific background effect.
"""
from functools import lru_cache

READS = ()
# Each vowel: magnitude with 0, 1, or 2 following letters, then next-token echo.
STRENGTH = {
    'ö': (4.25, 3.78, 1.91, 3.86),
    'ø': (3.80, 3.35, 1.81, 3.19),
    'ü': (2.90, 3.18, 1.74, 3.12),
    'ä': (1.01, 1.47, 1.11, 1.42),
    'æ': (0.96, 0.80, 0.76, 1.33),
}
FUNCTION_WORDS = {'für': 1.15, 'über': 1.10, 'för': 0.65, 'är': 0.25}
OTHER_LETTERS = {'ß': 0.60, 'å': 0.32, 'ő': 0.61, 'ű': 0.70, 'û': 0.47}

@lru_cache(maxsize=16384)
def fragment(token):
    word = token.strip()
    lower = word.lower()
    own, echo = 0.0, 0.0
    for i, raw in enumerate(word):
        c = raw.lower()
        if c not in STRENGTH:
            continue
        before = sum(ch.isalpha() for ch in word[:i])
        tail = ''.join(ch for ch in word[i+1:].lower() if ch.isalpha())
        after = len(tail)
        level = STRENGTH[c][min(after, 2)]
        if after == 1:
            if tail in 'td':       # dental stops
                level *= 1.11
            elif tail not in 'mnlr':   # not a nasal or liquid
                level *= 0.70
        level /= 1 + 0.36 * max(after-2, 0)
        scale = 0.675 ** before
        if before == 1 and lower[0] in 'mn':
            scale *= 1.19
        if raw.isupper():
            scale *= 0.86
        own = max(own, level * scale)
        echo = max(echo, STRENGTH[c][3] * scale * 0.59 ** after)
    if lower in FUNCTION_WORDS:
        own = FUNCTION_WORDS[lower]
    for c, level in OTHER_LETTERS.items():
        if c in lower:
            own += level / (1 + 0.5 * max(len(word)-1, 0))
    return own, echo

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_echo = carry[1] if carry is not None and carry[0] == doc else 0.0
    token = prefix.token_strings[-1]
    own, echo = fragment(token)
    following = 0.0
    if token and token[0].isalpha():
        letters = sum(c.isalpha() for c in token)
        following = old_echo * 0.81 ** max(0, letters-2)
        if any(c in 'aeiouyäöüæø' for c in token.lower()):
            following *= 0.71
    return (doc, echo), float(-own-following)
